import * as React from "react"
import {
  ThreadPrimitive,
  useAuiState,
  type ToolCallMessagePartComponent,
} from "@assistant-ui/react"
import {
  useAdkAgentInfo,
  useAdkArtifacts,
  useAdkAuthRequests,
  useAdkEscalation,
  useAdkLongRunningToolIds,
  useAdkSend,
  useAdkSessionState,
  useAdkSubmitAuth,
  useAdkSubmitInput,
  type AdkAuthCredential,
} from "@assistant-ui/react-google-adk"
import {
  Cancel01Icon,
  SecurityCheckIcon,
  Tick02Icon,
} from "@hugeicons/core-free-icons"
import { cn } from "cn"

import { ThreadFollowupSuggestions } from "@/components/assistant-ui/elements/follow-up-suggestions.aui"
import { ToolFallback } from "@/components/assistant-ui/elements/tool-fallback.aui"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireProgress,
  QuestionnaireSkip,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/components/ui/questionnaire"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Spinner } from "@/components/ui/spinner"
import { AgentOrb } from "@/components/forge/avatars"
import { Icon } from "@/components/forge/icon"
import type { IconProp } from "@/components/forge/icons"
import { CountBadge } from "@/components/forge/status"

import { useAssistantSettings, type ApprovalView } from "./assistant-context"
import { createArtifactFeedback } from "./artifact-feedback"
import { SearchLabel, type AssistantSearch } from "./sources"
import { answerFrom, askForm, describeAnswer } from "./ask-person"
import {
  approvalBatch,
  approvalWords,
  pendingApprovals,
  shownArguments,
} from "./approvals"
import { followUpsOf } from "./follow-ups"
import {
  compactTokens,
  contextView,
  currentContext,
  fullTokens,
  percent,
  type ContextView,
} from "./context-window"
import { extendedThinkingLevels } from "./model-settings"
import {
  ModelSelectorRoot,
  ModelSelectorTrigger,
  ModelSelectorContent,
  ModelSelectorSearch,
  ModelSelectorList,
  ModelSelectorEmpty,
  ModelSelectorGroup,
  ModelSelectorItem,
  ModelSelectorEffort,
  type ModelOption,
} from "@/components/assistant-ui/elements/model-selector"

/* -------------------------------------------------------------------------- */
/* Shared                                                                     */
/* -------------------------------------------------------------------------- */

/** "search_agent" → "Search agent". */
const humanize = (name: string) =>
  name.replace(/[_-]+/g, " ").replace(/^\w/, (c) => c.toUpperCase())

/** What an agent is called: its name in `agents`, or its own, humanized. */
function useAgentName() {
  const { agents } = useAssistantSettings()
  return React.useCallback(
    (name: string) =>
      (Object.hasOwn(agents ?? {}, name) ? agents?.[name] : undefined) ??
      humanize(name),
    [agents]
  )
}

/** Stable orb gradient per agent name. */
const orbVariant = (name: string) =>
  [...name].reduce((sum, char) => sum + char.charCodeAt(0), 0)

/** ADK messages use markdown code spans; render them as inline code. */
function InlineText({ text }: { text: string }) {
  return text.split(/(`[^`]+`)/).map((piece, index) =>
    piece.startsWith("`") && piece.endsWith("`") ? (
      <code key={index} className="font-mono text-foreground">
        {piece.slice(1, -1)}
      </code>
    ) : (
      piece
    )
  )
}

/** Tool results arrive as JSON text or values; unwrap ADK's `{ result }`. */
const unwrapResult = (result: unknown): unknown => {
  let value = result
  if (typeof value === "string") {
    try {
      value = JSON.parse(value)
    } catch {
      return value
    }
  }
  return typeof value === "object" && value !== null && "result" in value
    ? (value as { result: unknown }).result
    : value
}

/** A human-in-the-loop request, inline in the conversation. */
function RequestCard({
  icon,
  title,
  description,
  done,
  plain = false,
  children,
}: {
  icon: IconProp
  title: React.ReactNode
  description?: React.ReactNode
  done?: React.ReactNode
  /** Part of the reply, without the card's outline and fill. */
  plain?: boolean
  children?: React.ReactNode
}) {
  return (
    <div
      data-slot="adk-request"
      data-plain={plain || undefined}
      className={cn(
        "my-2 flex flex-col gap-3 text-xs",
        !plain && "rounded-(--radius-card) border border-border bg-card p-3.5"
      )}
    >
      <div className="flex items-start gap-2.5">
        <span className="flex size-7 shrink-0 items-center justify-center rounded-(--radius-soft) bg-muted text-muted-foreground">
          <Icon icon={done ? "check" : icon} size={15} />
        </span>
        <div className="flex min-w-0 flex-1 flex-col gap-0.5 pt-px">
          <p className="font-medium text-foreground">{title}</p>
          {description && (
            <p className="leading-relaxed text-muted-foreground">
              {description}
            </p>
          )}
        </div>
      </div>
      {done ? (
        <p className="flex items-center gap-1.5 text-muted-foreground">
          {done}
        </p>
      ) : (
        children
      )}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/* Auth requests (adk_request_credential)                                     */
/* -------------------------------------------------------------------------- */

const authUriOf = (authConfig: unknown) =>
  (authConfig as { exchangedAuthCredential?: AdkAuthCredential } | undefined)
    ?.exchangedAuthCredential?.oauth2?.authUri

const hostOf = (uri: string | undefined) => {
  if (!uri) return undefined
  try {
    return new URL(uri).host
  } catch {
    return undefined
  }
}

/**
 * Renders ADK's `adk_request_credential` call: a sign-in card that hands the
 * request to `onAuthRequest` and submits the credential it resolves with.
 */
export const AdkAuthRequestUI: ToolCallMessagePartComponent<
  { authConfig?: unknown; auth_config?: unknown },
  unknown
> = ({ toolCallId, args, result }) => {
  const { onAuthRequest } = useAssistantSettings()
  const requests = useAdkAuthRequests()
  const submitAuth = useAdkSubmitAuth()
  const [pending, setPending] = React.useState(false)
  const [error, setError] = React.useState<string>()

  const request = requests.find((r) => r.toolCallId === toolCallId)
  // The call's own arguments carry the auth config after it's answered, too.
  const authUri = authUriOf(
    request?.authConfig ?? args.authConfig ?? args.auth_config
  )
  const host = hostOf(authUri)

  const signIn = async () => {
    if (!request || !onAuthRequest) return
    setPending(true)
    setError(undefined)
    try {
      const credential = await onAuthRequest({ ...request, authUri })
      await submitAuth(toolCallId, credential)
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Sign-in failed.")
    } finally {
      setPending(false)
    }
  }

  return (
    <RequestCard
      icon="link"
      title="Sign-in required"
      description={
        host
          ? `The agent needs access to ${host} to continue.`
          : "The agent needs you to sign in to continue."
      }
      done={
        result !== undefined || (!request && !pending) ? (
          <>Signed in{host ? ` to ${host}` : ""}.</>
        ) : undefined
      }
    >
      <div className="flex flex-wrap items-center gap-2">
        <Button size="sm" disabled={pending || !onAuthRequest} onClick={signIn}>
          {pending && <Spinner data-icon="inline-start" />}
          {pending ? "Waiting for sign-in…" : "Sign in"}
        </Button>
        {!onAuthRequest && (
          <span className="text-muted-foreground">
            Pass <code>onAuthRequest</code> to complete sign-in.
          </span>
        )}
        {error && <span className="text-destructive">{error}</span>}
      </div>
    </RequestCard>
  )
}

/* -------------------------------------------------------------------------- */
/* Input requests (adk_request_input)                                         */
/* -------------------------------------------------------------------------- */

type RequestInputArgs = {
  message?: string
  response_schema?: unknown
}

/**
 * Renders ADK's `adk_request_input` call (an agent asking the person, or a
 * Workflow `RequestInput` node) as a form: a `Questionnaire` with a question
 * per field of its `response_schema` (one at a time, with progress), or one
 * question for any other schema: pick one, pick several, yes or no, or a typed
 * answer (text, number, email, URL, date…). The answer goes back in the
 * schema's types (`answerFrom`), and the turn carries on.
 */
export const AdkInputRequestUI: ToolCallMessagePartComponent<
  RequestInputArgs,
  unknown
> = ({ toolCallId, args, result }) => {
  const submitInput = useAdkSubmitInput()
  const [pending, setPending] = React.useState(false)
  const message = args.message?.trim() || "Please provide input to continue."
  const form = React.useMemo(
    () => askForm(args.response_schema, message),
    [args.response_schema, message]
  )
  const several = form.questions.length > 1

  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const answer = answerFrom(form, new FormData(event.currentTarget))
    setPending(true)
    try {
      await submitInput(toolCallId, answer)
    } finally {
      setPending(false)
    }
  }

  const answered = result === undefined ? undefined : unwrapResult(result)
  return (
    <RequestCard
      icon="message"
      title="The agent has a question"
      plain
      // One question is its own title, unless its schema names it (then
      // the message, say a summary to confirm, goes above it); a form's
      // questions are its fields.
      description={
        form.fields || form.questions[0]?.title !== message ? (
          <InlineText text={message} />
        ) : undefined
      }
      done={
        answered !== undefined ? (
          <>Answered: {describeAnswer(answered, form)}</>
        ) : undefined
      }
    >
      <Questionnaire
        onSubmit={submit}
        aria-busy={pending}
        aria-label={message}
        className="gap-3"
      >
        {several && <QuestionnaireProgress />}
        {form.questions.map((question) => (
          <QuestionnaireItem
            key={question.name}
            name={question.name}
            required={question.required}
            multiple={question.kind === "multiple"}
            disabled={pending}
          >
            <QuestionnaireTitle>
              {form.fields ? (
                question.title
              ) : (
                <InlineText text={question.title} />
              )}
            </QuestionnaireTitle>
            {question.description && (
              <QuestionnaireDescription>
                {question.description}
              </QuestionnaireDescription>
            )}
            {question.choices ? (
              <QuestionnaireChoices>
                {question.choices.map((choice) => (
                  <QuestionnaireChoice
                    key={choice.value}
                    value={choice.value}
                    defaultChecked={question.defaults.includes(choice.value)}
                  >
                    {choice.label}
                  </QuestionnaireChoice>
                ))}
              </QuestionnaireChoices>
            ) : (
              <QuestionnaireInput
                type={question.input?.type}
                placeholder={question.input?.placeholder}
                min={question.input?.min}
                max={question.input?.max}
                step={question.input?.step}
                defaultValue={question.defaults[0]}
                aria-label={question.title}
              />
            )}
            <QuestionnaireError />
          </QuestionnaireItem>
        ))}
        <QuestionnaireActions>
          {several && <QuestionnairePrevious />}
          <QuestionnaireSkip />
          {several && <QuestionnaireNext />}
          <QuestionnaireSubmit disabled={pending}>
            {pending && <Spinner data-icon="inline-start" />}
            Send
          </QuestionnaireSubmit>
        </QuestionnaireActions>
      </Questionnaire>
    </RequestCard>
  )
}

/* -------------------------------------------------------------------------- */
/* Tool confirmations (adk_request_confirmation)                              */
/* -------------------------------------------------------------------------- */

type ConfirmationArgs = {
  originalFunctionCall?: { name?: string; args?: Record<string, unknown> }
  original_function_call?: { name?: string; args?: Record<string, unknown> }
  toolConfirmation?: { hint?: string }
  tool_confirmation?: { hint?: string }
}

/** A small pulsing dot: this is waiting on the person. */
function WaitingDot() {
  return (
    <span aria-hidden className="relative flex size-1.5">
      <span className="absolute inline-flex size-full animate-ping rounded-full bg-warning-foreground opacity-60 motion-reduce:animate-none" />
      <span className="relative inline-flex size-1.5 rounded-full bg-warning-foreground" />
    </span>
  )
}

/**
 * This card's part in its turn's approvals (`approvals.ts`): the person's
 * decision is held until every approval of the turn is decided and no run
 * is going, then one card sends them all at once.
 */
function useTurnApproval(toolCallId: string) {
  const send = useAdkSend()
  const version = React.useSyncExternalStore(
    approvalBatch.subscribe,
    approvalBatch.version
  )
  const pendingKey = useAuiState((s) =>
    pendingApprovals(s.message.parts).join(" ")
  )
  const running = useAuiState((s) => s.thread.isRunning)
  const [error, setError] = React.useState<string>()
  const pending = React.useMemo(
    () => (pendingKey ? pendingKey.split(" ") : []),
    [pendingKey]
  )

  React.useEffect(() => {
    if (running) return
    // Only the first card to ask gets them, so they go once.
    const replies = approvalBatch.take(pending)
    if (!replies) return
    send(replies, {}).catch((reason: unknown) => {
      approvalBatch.release(pending)
      setError(reason instanceof Error ? reason.message : String(reason))
    })
  }, [pending, running, send, version])

  return {
    decision: approvalBatch.decisionOf(toolCallId),
    sent: approvalBatch.isSent(toolCallId),
    /** The turn's other approvals still to decide. */
    others: pending.filter(
      (id) => id !== toolCallId && approvalBatch.decisionOf(id) === undefined
    ).length,
    running,
    error,
    decide: (confirmed: boolean) => {
      setError(undefined)
      approvalBatch.decide(toolCallId, confirmed)
    },
    undo: () => approvalBatch.undo(toolCallId),
  }
}

/** Why a decision hasn't gone yet. */
const waitingFor = (others: number, running: boolean) =>
  others > 0
    ? `It's sent once you've answered the other ${others === 1 ? "request" : `${others} requests`}.`
    : running
      ? "It's sent once the assistant has finished."
      : "Sending…"

/**
 * The call's arguments, when the tool has no preview of its own: by name
 * and without IDs (`shownArguments`).
 */
function ArgumentList({ args }: { args: Record<string, unknown> }) {
  const shown = shownArguments(args)
  if (shown.length === 0) return null
  return (
    <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1.5 rounded-(--radius-soft) border border-border/60 bg-muted/60 px-3 py-2 text-xs">
      {shown.map(({ key, label, value }) => (
        <React.Fragment key={key}>
          <dt className="text-muted-foreground">{label}</dt>
          <dd className="min-w-0 break-words whitespace-pre-line text-foreground">
            {typeof value === "string" ? (
              value
            ) : (
              <ul className="flex list-disc flex-col gap-0.5 ps-4">
                {value.map((item, index) => (
                  <li key={index}>{item}</li>
                ))}
              </ul>
            )}
          </dd>
        </React.Fragment>
      ))}
    </dl>
  )
}

/** Once decided, the card folds to one line saying what the person chose. */
function ApprovalOutcome({
  approved,
  question,
  view,
}: {
  approved: boolean
  /** What the card asked. */
  question: string
  view: ApprovalView | undefined
}) {
  return (
    <p
      data-slot="adk-approval-outcome"
      className="my-1 flex animate-in items-center gap-2 text-xs text-muted-foreground duration-300 fade-in"
    >
      <span
        className={cn(
          "flex size-4 shrink-0 items-center justify-center rounded-full",
          approved
            ? "bg-success-surface text-success-foreground"
            : "bg-muted text-muted-foreground"
        )}
      >
        <Icon icon={approved ? Tick02Icon : Cancel01Icon} size={10} />
      </span>
      {approved
        ? (view?.approvedLabel ?? `Approved: ${question}`)
        : (view?.deniedLabel ?? `Denied: ${question}`)}
    </p>
  )
}

/**
 * Renders ADK's `adk_request_confirmation` call, which a tool with
 * `require_confirmation` makes before it runs: a card saying what the agent
 * wants to do (the tool's `ApprovalView` in `approvals`, else the tool's own
 * question in its hint, else in general terms) over the call's arguments
 * without IDs, with Approve / Deny. The run waits until the person decides;
 * several approvals of one turn are answered together (`useTurnApproval`).
 * The card then folds to the outcome. The gated call itself renders without
 * controls (see `AdkToolFallback`), so the decision is made in one place.
 */
export const AdkConfirmationUI: ToolCallMessagePartComponent<
  ConfirmationArgs,
  unknown
> = ({ toolCallId, args, approval }) => {
  const turn = useTurnApproval(toolCallId)
  const { approvals } = useAssistantSettings()
  const original = args.originalFunctionCall ?? args.original_function_call
  const toolName = original?.name ?? "tool"
  const callArgs = original?.args ?? {}
  const view = approvals?.[toolName]
  const words = approvalWords(
    original?.name ?? "",
    (args.toolConfirmation ?? args.tool_confirmation)?.hint
  )
  const Preview = view?.preview
  const answered = approval?.approved ?? (turn.sent ? turn.decision : undefined)

  if (answered !== undefined)
    return (
      <ApprovalOutcome
        approved={answered}
        question={words.question}
        view={view}
      />
    )

  return (
    <section
      data-slot="adk-approval"
      aria-label="Needs your approval"
      className="my-2 animate-in overflow-hidden rounded-(--radius-card) border border-warning-foreground/25 bg-card shadow-sm duration-300 fade-in slide-in-from-bottom-1"
    >
      <header className="flex items-center gap-2 border-b border-warning-foreground/15 bg-warning-surface px-3.5 py-2 text-xs text-warning-foreground">
        <Icon icon={SecurityCheckIcon} size={14} />
        <span className="font-medium">Needs your approval</span>
        <span className="ms-auto flex items-center gap-1.5 opacity-90">
          <WaitingDot />
          Waiting for you
        </span>
      </header>
      <div className="flex flex-col gap-3 p-3.5">
        <div className="flex flex-col gap-1">
          <p className="text-sm font-medium text-foreground">
            {view?.title ?? words.question}
          </p>
          <p className="text-xs leading-relaxed text-muted-foreground">
            {view?.description ??
              (words.detail ? (
                <InlineText text={words.detail} />
              ) : (
                "The assistant wants to do this. Nothing happens until you approve it."
              ))}
          </p>
        </div>
        {Preview ? (
          <Preview args={callArgs} />
        ) : (
          <ArgumentList args={callArgs} />
        )}
        {turn.decision === undefined ? (
          <div className="flex flex-wrap items-center gap-2">
            <Button size="sm" onClick={() => turn.decide(true)}>
              <Icon icon={Tick02Icon} data-icon="inline-start" />
              {view?.approveLabel ?? "Approve"}
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => turn.decide(false)}
            >
              Deny
            </Button>
            {turn.error && (
              <span className="text-xs text-destructive">{turn.error}</span>
            )}
          </div>
        ) : (
          <div className="flex items-start gap-2 text-xs text-muted-foreground">
            {turn.others === 0 && !turn.running ? (
              <Spinner className="mt-px shrink-0" />
            ) : (
              <Icon
                icon={turn.decision ? Tick02Icon : Cancel01Icon}
                size={12}
                className="mt-0.5 shrink-0"
              />
            )}
            <p className="min-w-0 flex-1 leading-relaxed">
              {turn.decision ? "Approved." : "Denied."}{" "}
              {waitingFor(turn.others, turn.running)}
            </p>
            <Button
              size="xs"
              variant="ghost"
              className="-my-0.5 shrink-0"
              onClick={turn.undo}
            >
              Change
            </Button>
          </div>
        )}
      </div>
    </section>
  )
}

const textOf = (value: unknown, key: string) => {
  if (typeof value === "string") return value
  const field =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)[key]
      : undefined
  return typeof field === "string" ? field : undefined
}

/**
 * A call handing a request to one of the app's agents (`agents`), e.g. an
 * ADK supervisor's specialist: what it was asked and what it reported. It
 * shows in the message rather than folded into the tool calls, so the
 * person sees who is working on it.
 */
export const AdkDelegation: ToolCallMessagePartComponent = ({
  toolName,
  args,
  argsText,
  result,
  status,
}) => {
  const agentName = useAgentName()
  const request = textOf(args, "request") ?? textOf(args, "background")
  const report = textOf(result, "result")
  return (
    <ToolFallback.Root data-slot="adk-delegation">
      <ToolFallback.Trigger
        toolName={toolName}
        status={status}
        label={
          <>
            Asked <b>{agentName(toolName)}</b>
          </>
        }
      />
      <ToolFallback.Content>
        <ToolFallback.Error status={status} />
        {request !== undefined ? (
          <p className="whitespace-pre-line text-muted-foreground">{request}</p>
        ) : (
          <ToolFallback.Args argsText={argsText} />
        )}
        {report !== undefined ? (
          <div className="flex flex-col gap-1">
            <p className="text-xs font-medium text-muted-foreground">
              Reported:
            </p>
            <p className="whitespace-pre-line text-foreground/90">{report}</p>
          </div>
        ) : (
          <ToolFallback.Result result={result} />
        )}
      </ToolFallback.Content>
    </ToolFallback.Root>
  )
}

/**
 * `ToolFallback` for ADK: a call gated by a confirmation shows its trigger,
 * arguments and result but no approval controls, since
 * `AdkConfirmationUI` owns the decision. A search (the sources config's
 * `searchOf`) says what it searched and found. Other calls render as usual.
 */
/** The search a finished tool call made, as the sources config reads it. */
function useToolSearch(
  toolName: string,
  result: unknown
): AssistantSearch | undefined {
  const searchOf = useAssistantSettings().sources?.searchOf
  return React.useMemo(() => {
    if (!searchOf || result === undefined) return undefined
    try {
      return searchOf(toolName, result)
    } catch {
      return undefined // a result the config can't read is just a tool call
    }
  }, [searchOf, toolName, result])
}

export const AdkToolFallback: ToolCallMessagePartComponent = (props) => {
  const search = useToolSearch(props.toolName, props.result)
  if (!props.approval && !search) return <ToolFallback {...props} />
  return (
    <ToolFallback.Root>
      <ToolFallback.Trigger
        toolName={props.toolName}
        status={props.status}
        label={search && <SearchLabel search={search} />}
      />
      <ToolFallback.Content>
        <ToolFallback.Error status={props.status} />
        <ToolFallback.Args argsText={props.argsText} />
        <ToolFallback.Result result={props.result} />
      </ToolFallback.Content>
    </ToolFallback.Root>
  )
}

/* -------------------------------------------------------------------------- */
/* Session-level status                                                       */
/* -------------------------------------------------------------------------- */

/** The agent currently answering (multi-agent apps), for the top bar. */
function AdkAgentIndicator({ className }: { className?: string }) {
  const agent = useAdkAgentInfo()
  const agentName = useAgentName()
  if (!agent?.name) return null
  return (
    <span
      data-slot="adk-agent"
      title={agent.branch}
      className={cn(
        "flex shrink-0 items-center gap-1.5 text-xs whitespace-nowrap text-muted-foreground",
        className
      )}
    >
      <AgentOrb variant={orbVariant(agent.name)} />
      <span className="text-foreground">{agentName(agent.name)}</span>
    </span>
  )
}

const authorOf = (metadata: { custom?: Record<string, unknown> }) =>
  typeof metadata.custom?.author === "string"
    ? metadata.custom.author
    : undefined

/**
 * The agent that wrote an assistant message, for multi-agent conversations:
 * shown where the speaking agent changes, hidden while only one agent talks.
 */
function AdkMessageAuthor() {
  const agentName = useAgentName()
  const author = useAuiState((s) => authorOf(s.message.metadata))
  const changed = useAuiState((s) => {
    for (let index = s.message.index - 1; index >= 0; index--) {
      const previous = s.thread.messages[index]
      if (previous?.role === "assistant") {
        return authorOf(previous.metadata) !== authorOf(s.message.metadata)
      }
    }
    return true
  })
  const multiAgent = useAuiState(
    (s) =>
      new Set(
        s.thread.messages
          .filter((m) => m.role === "assistant")
          .map((m) => authorOf(m.metadata))
          .filter(Boolean)
      ).size > 1
  )
  if (!author || !multiAgent || !changed) return null
  return (
    <div
      data-slot="adk-message-author"
      className="mb-1.5 flex items-center gap-1.5 text-2xs text-muted-foreground"
    >
      <AgentOrb variant={orbVariant(author)} className="size-3.5" />
      {agentName(author)}
    </div>
  )
}

/** Shown once the agent escalates the conversation to a person. */
function AdkEscalationBanner({
  children = "The agent handed this conversation to a person. They'll reply here.",
  className,
}: {
  children?: React.ReactNode
  className?: string
}) {
  const escalated = useAdkEscalation()
  if (!escalated) return null
  return (
    <div
      role="status"
      data-slot="adk-escalation"
      className={cn(
        "flex items-center gap-2 border-b border-notice-border bg-notice-surface px-5 py-2 text-xs text-notice-foreground",
        className
      )}
    >
      <Icon icon="team" size={15} />
      {children}
    </div>
  )
}

const downloadArtifact = (
  name: string,
  data: {
    text?: string
    inlineData?: { data: string; mimeType: string }
    fileData?: { fileUri: string }
  }
) => {
  if (data.fileData?.fileUri) {
    window.open(data.fileData.fileUri, "_blank", "noopener")
    return
  }
  const blob = data.inlineData
    ? new Blob(
        [Uint8Array.from(atob(data.inlineData.data), (c) => c.charCodeAt(0))],
        { type: data.inlineData.mimeType }
      )
    : new Blob([data.text ?? ""], { type: "text/plain" })
  const url = URL.createObjectURL(blob)
  const link = Object.assign(document.createElement("a"), {
    href: url,
    download: name,
  })
  link.click()
  URL.revokeObjectURL(url)
}

/**
 * Files the agent saved in this session. Downloads need `artifacts` from
 * `useAdkAssistant` (direct ADK connections); otherwise they're listed only.
 * `compact` drops the label, for tight headers.
 */
function AdkArtifactsMenu({ compact = false }: { compact?: boolean }) {
  const artifacts = useAdkArtifacts()
  const { artifacts: api, onOpenArtifact } = useAssistantSettings()
  const sessionId = useAuiState((s) => {
    const current = s.threads.threadItems.find(
      (t) => t.id === s.threads.mainThreadId
    )
    return current?.externalId ?? current?.remoteId
  })
  const feedback = React.useMemo(
    () =>
      createArtifactFeedback({
        api,
        sessionId,
        onOpenArtifact,
        download: downloadArtifact,
      }),
    [api, sessionId, onOpenArtifact]
  )
  React.useEffect(() => () => feedback.cancelPending(), [feedback])
  const state = React.useSyncExternalStore(
    feedback.subscribe,
    feedback.getSnapshot,
    feedback.getSnapshot
  )
  const names = [...new Set([...Object.keys(artifacts), ...state.names])]
  const busy = state.loading || Boolean(state.pending)
  if (names.length === 0 && (!api || !sessionId)) return null

  return (
    <DropdownMenu
      onOpenChange={(open) => {
        if (open) void feedback.refresh()
      }}
    >
      <DropdownMenuTrigger
        render={
          compact ? (
            <Button
              variant="ghost"
              size="sm"
              className="h-7 gap-1 px-1.5 text-muted-foreground"
            />
          ) : (
            <Button variant="outline" size="sm" />
          )
        }
        aria-label={`Artifacts (${names.length})`}
      >
        <Icon icon="file" data-icon="inline-start" />
        {!compact && "Artifacts"}
        <CountBadge>{names.length}</CountBadge>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-56">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Saved by the agent</DropdownMenuLabel>
          {state.loading && (
            <div
              role="status"
              className="flex items-center gap-2 px-2 py-2 text-xs text-muted-foreground"
            >
              <Spinner className="size-3" /> Loading saved files…
            </div>
          )}
          {!state.loading && !state.error && names.length === 0 && (
            <p className="px-2 py-2 text-xs text-muted-foreground">
              No saved files yet.
            </p>
          )}
          {names.map((name) => (
            <DropdownMenuItem
              key={name}
              closeOnClick={false}
              disabled={busy || (!onOpenArtifact && (!api || !sessionId))}
              onClick={() => {
                void feedback.open(name)
              }}
            >
              {state.pending === name ? (
                <Spinner className="size-4" />
              ) : (
                <Icon icon="file" />
              )}
              <span className="min-w-0 flex-1 truncate">{name}</span>
              {artifacts[name] !== undefined && (
                <span className="text-2xs text-muted-foreground">
                  v{artifacts[name]}
                </span>
              )}
            </DropdownMenuItem>
          ))}
          {state.error && (
            <div
              role="alert"
              className="max-w-72 px-2 py-2 text-xs text-danger-foreground"
            >
              <p>{state.error.message}</p>
              <Button
                size="sm"
                variant="outline"
                className="mt-2"
                disabled={busy}
                onClick={() => {
                  void feedback.retry()
                }}
              >
                Retry
              </Button>
            </div>
          )}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

