/**
 * Tool approvals (ADK's `adk_request_confirmation`): what the card asks,
 * which of the call's arguments it shows, and the person's decisions, held
 * until every approval of the turn is answered.
 *
 * A reply to one approval resumes the run at once. Answering a second one
 * while that run goes on would start another run on the same session, which
 * ADK refuses ("The session has been modified in storage since it was
 * loaded"). So the approvals one turn asked for are answered together: each
 * decision waits here until the turn's last one is made (and no run is
 * going), then they all go in one message, which resumes every call in one
 * run.
 */

export const CONFIRMATION_TOOL = "adk_request_confirmation"

// ADK's own hint, from `require_confirmation`, is written for the client that
// answers it ("... by responding with a FunctionResponse ..."), not for the
// person; the card says it in its own words.
export const ADK_PROTOCOL_HINT = /^Please approve or reject the tool call /

/** "test_agent" → "Test agent"; "dryRun" → "Dry run". */
export const humanizeName = (name: string) =>
  name
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .trim()
    .toLowerCase()
    .replace(/^\w/, (c) => c.toUpperCase())

export type ApprovalWords = {
  /** What the card asks: "Try “Support” with this message?" */
  question: string
  /** What approving does, when the tool says. */
  detail: string | undefined
}

/**
 * What the card says for a call to `toolName`. A hint whose first line is a
 * question (Forge's tools word theirs so) is the card's question, and its
 * other lines say what approving does; any other hint explains a general
 * question; ADK's own hint is no hint.
 */
export function approvalWords(
  toolName: string,
  hint: string | undefined
): ApprovalWords {
  const general = `Allow “${humanizeName(toolName) || "this tool"}”?`
  const text = hint?.trim()
  if (!text || ADK_PROTOCOL_HINT.test(text))
    return { question: general, detail: undefined }
  const [first = "", ...rest] = text.split("\n")
  if (!first.trim().endsWith("?")) return { question: general, detail: text }
  const detail = rest.join(" ").replace(/\s+/g, " ").trim()
  return { question: first.trim(), detail: detail || undefined }
}

export type ShownArgument = {
  key: string
  label: string
  /** One value, or each of a list's. */
  value: string | readonly string[]
}

// An ID in UUID form, alone or scoped (org:<ID>).
const UUID =
  /^([a-z]+:)?[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
// Forge's own IDs: a short prefix and a code with a digit (ca_k2x8d1q, ag_…).
const FORGE_ID = /^[a-z]{2,4}_(?=[a-z0-9]*\d)[a-z0-9]{6,}(@[a-z]+)?$/
// organization_id, agentId, permission_ids, id ...
const ID_KEY = /(^|_)ids?$|[a-z]Ids?$/
// The most characters of one value the card shows.
const VALUE_CHARS = 400

const clip = (text: string) =>
  text.length > VALUE_CHARS ? `${text.slice(0, VALUE_CHARS - 1)}…` : text

const isId = (value: unknown) =>
  typeof value === "string" && (UUID.test(value) || FORGE_ID.test(value))

const scalar = (value: unknown): string | undefined => {
  if (typeof value === "boolean") return value ? "Yes" : "No"
  if (typeof value === "number") return String(value)
  if (typeof value === "string") return value.trim() ? clip(value) : undefined
  return undefined
}

const shown = (value: unknown): string | readonly string[] | undefined => {
  if (value == null || isId(value)) return undefined
  const one = scalar(value)
  if (one !== undefined || typeof value !== "object") return one
  const entries = Array.isArray(value)
    ? value.map((item) => [undefined, item] as const)
    : Object.entries(value).map(([key, item]) => [key, item] as const)
  const lines: string[] = []
  for (const [key, item] of entries) {
    if (item == null || isId(item) || (key && ID_KEY.test(key))) continue
    const text =
      typeof item === "object" ? clip(JSON.stringify(item)) : scalar(item)
    if (text === undefined) continue
    lines.push(key ? `${humanizeName(key)}: ${text}` : text)
  }
  return lines.length ? lines : undefined
}

/**
 * The call's arguments as the card lists them, for someone who isn't
 * technical: by name, without the IDs (the question names what they point
 * at), empty values or JSON where a list or a word will do.
 */
export function shownArguments(
  args: Readonly<Record<string, unknown>> | undefined
): ShownArgument[] {
  const found: ShownArgument[] = []
  for (const [key, raw] of Object.entries(args ?? {})) {
    if (ID_KEY.test(key)) continue
    const value = shown(raw)
    if (value !== undefined)
      found.push({ key, label: humanizeName(key), value })
  }
  return found
}

type PartLike = {
  type?: string
  toolName?: string
  toolCallId?: string
  result?: unknown
  approval?: { approved?: boolean }
}

/** The approvals still waiting in a message's parts, by their call's ID, in order. */
export function pendingApprovals(parts: readonly unknown[]): string[] {
  return parts.flatMap((raw) => {
    const part = raw as PartLike
    return part.type === "tool-call" &&
      part.toolName === CONFIRMATION_TOOL &&
      part.toolCallId &&
      part.result === undefined &&
      part.approval?.approved === undefined
      ? [part.toolCallId]
      : []
  })
}

/** The reply ADK resumes a call on, as the ADK runtime sends it. */
export type ConfirmationReply = {
  id: string
  type: "tool"
  tool_call_id: string
  name: typeof CONFIRMATION_TOOL
  content: string
  status: "success"
}

export const confirmationReply = (
  toolCallId: string,
  confirmed: boolean,
  id: string = crypto.randomUUID()
): ConfirmationReply => ({
  id,
  type: "tool",
  tool_call_id: toolCallId,
  name: CONFIRMATION_TOOL,
  content: JSON.stringify({ confirmed }),
  status: "success",
})

export type ApprovalBatch = ReturnType<typeof createApprovalBatch>

/**
 * The person's decisions on approvals, by their call's ID, until they're
 * sent. Several cards share one, and read it with `subscribe` and
 * `version` (`useSyncExternalStore`).
 */
export function createApprovalBatch() {
  const decisions = new Map<string, boolean>()
  const sent = new Set<string>()
  const listeners = new Set<() => void>()
  let version = 0
  const changed = () => {
    version += 1
    for (const listener of listeners) listener()
  }
  return {
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    version: () => version,
    /** The decision made on an approval and not sent yet, if any. */
    decisionOf: (toolCallId: string) => decisions.get(toolCallId),
    isSent: (toolCallId: string) => sent.has(toolCallId),
    decide(toolCallId: string, confirmed: boolean) {
      if (sent.has(toolCallId)) return
      decisions.set(toolCallId, confirmed)
      changed()
    },
    /** Takes a decision back before it's sent. */
    undo(toolCallId: string) {
      if (!sent.has(toolCallId) && decisions.delete(toolCallId)) changed()
    },
    /**
     * The replies to every approval in `pending`, once each is decided and
     * none has been sent; they count as sent from then on. Otherwise
     * nothing, so only one card sends them.
     */
    take(pending: readonly string[]): ConfirmationReply[] | undefined {
      if (
        pending.length === 0 ||
        pending.some((id) => !decisions.has(id) || sent.has(id))
      )
        return undefined
      for (const id of pending) sent.add(id)
      changed()
      return pending.map((id) => confirmationReply(id, decisions.get(id)!))
    },
    /** Sending failed: the approvals can be decided and sent again. */
    release(toolCallIds: readonly string[]) {
      for (const id of toolCallIds) {
        sent.delete(id)
        decisions.delete(id)
      }
      changed()
    },
  }
}

/** The decisions of every conversation's approvals: call IDs are unique. */
export const approvalBatch = createApprovalBatch()

import type { AdkArtifactData } from "@assistant-ui/react-google-adk"

type ArtifactApi = {
  list(sessionId: string): Promise<string[]>
  load(sessionId: string, name: string): Promise<AdkArtifactData>
}
export type ArtifactFeedbackState = {
  names: readonly string[]
  loading: boolean
  pending?: string
  error?: { action: "list" | "download"; name?: string; message: string }
}

/** Keep asynchronous file failures visible and prevent stale session downloads. */
export function createArtifactFeedback({
  api,
  sessionId,
  onOpenArtifact,
  download,
}: {
  api?: ArtifactApi
  sessionId?: string
  onOpenArtifact?: (name: string) => void | Promise<void>
  download: (name: string, data: AdkArtifactData) => void
}) {
  let state: ArtifactFeedbackState = { names: [], loading: false }
  let request = 0
  const listeners = new Set<() => void>()
  const publish = (next: ArtifactFeedbackState) => {
    state = next
    for (const listener of listeners) listener()
  }
  const refresh = async () => {
    if (!api || !sessionId || state.loading || state.pending) return
    const token = ++request
    publish({ ...state, loading: true, error: undefined })
    try {
      const names = await api.list(sessionId)
      if (
        !Array.isArray(names) ||
        !names.every((name) => typeof name === "string" && name)
      )
        throw new Error("Invalid artifact list")
      if (token === request)
        publish({ names: [...new Set(names)], loading: false })
    } catch {
      if (token === request)
        publish({
          ...state,
          loading: false,
          error: {
            action: "list",
            message:
              "Saved files couldn't be loaded. Check your connection and retry.",
          },
        })
    }
  }
  const open = async (name: string) => {
    if (
      state.loading ||
      state.pending ||
      (!onOpenArtifact && (!api || !sessionId))
    )
      return
    const token = ++request
    publish({ ...state, pending: name, error: undefined })
    try {
      if (onOpenArtifact) await onOpenArtifact(name)
      else if (api && sessionId) {
        const data = await api.load(sessionId, name)
        if (token !== request) return
        download(name, data)
      }
      if (token === request) publish({ ...state, pending: undefined })
    } catch {
      if (token === request)
        publish({
          ...state,
          pending: undefined,
          error: {
            action: "download",
            name,
            message: `“${name}” couldn't be opened. Check your connection and retry.`,
          },
        })
    }
  }
  return {
    getSnapshot: () => state,
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    refresh,
    open,
    async retry() {
      const error = state.error
      if (error?.action === "list") await refresh()
      else if (error?.name) await open(error.name)
    },
    cancelPending() {
      request++
    },
  }
}

/**
 * An agent's question (ADK's `adk_request_input`) as a form: the questions
 * its `response_schema` asks, one per field of an object schema or one for
 * any other, and the answer read back from the form's data in the shape and
 * types the schema declares, as ADK checks it when the turn carries on.
 */

/** A JSON Schema, as far as a form for it reads one. */
export type AnswerSchema = {
  type?: string | string[]
  enum?: unknown[]
  items?: AnswerSchema
  properties?: Record<string, AnswerSchema>
  required?: string[]
  title?: string
  description?: string
  format?: string
  default?: unknown
  minimum?: number
  maximum?: number
}

/** An answer: what the schema describes, as JSON. */
export type Answer =
  string | number | boolean | null | Answer[] | { [key: string]: Answer }

/** The input types the form's free answers take. */
export type AnswerInputType =
  "text" | "number" | "email" | "url" | "date" | "datetime-local" | "time"

/** How an answer is read back: its JSON type. */
type Reading =
  "string" | "number" | "integer" | "boolean" | "list" | "json" | "choice"

export type Question = {
  /** Its name in the form's data: the field's, or `answer`. */
  name: string
  /** Shown as the question. */
  title: string
  description?: string
  required: boolean
  /** Pick one, pick several, or a free answer in an input. */
  kind: "single" | "multiple" | "input"
  choices?: { value: string; label: string }[]
  input?: {
    type: AnswerInputType
    placeholder?: string
    min?: number
    max?: number
    step?: number | "any"
  }
  /** What's filled in or picked before the person answers. */
  defaults: string[]
  reading: Reading
  /** A choice's value as the schema has it, by the form's value. */
  values?: Record<string, Answer>
}

export type AskForm = {
  questions: Question[]
  /** The answer is an object of the questions' answers; else the one answer. */
  fields: boolean
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

/** A schema's type, the first non-null when it lists several. */
function typeOf(schema: AnswerSchema): string | undefined {
  const type = schema.type
  if (Array.isArray(type)) return type.find((each) => each !== "null")
  return type
}

/** "dueDate" / "due_date" → "Due date". */
export function humanize(name: string) {
  const words = name
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .trim()
    .toLowerCase()
  return words ? words[0]!.toUpperCase() + words.slice(1) : name
}

const INPUT_FORMATS: Record<string, AnswerInputType> = {
  email: "email",
  uri: "url",
  url: "url",
  date: "date",
  "date-time": "datetime-local",
  time: "time",
}

const defaultsOf = (value: unknown): string[] =>
  value === undefined || value === null
    ? []
    : Array.isArray(value)
      ? value.map(String)
      : [isRecord(value) ? JSON.stringify(value) : String(value)]

/** One question for a schema: a field's, or the whole answer's. */
function question(
  name: string,
  raw: unknown,
  title: string,
  required: boolean
): Question {
  const schema: AnswerSchema = isRecord(raw) ? raw : {}
  const type = typeOf(schema)
  const base = {
    name,
    title: schema.title || title,
    ...(schema.description && { description: schema.description }),
    required,
    defaults: defaultsOf(schema.default),
  }
  if (schema.enum?.length) {
    const values = Object.fromEntries(
      schema.enum.map((value) => [String(value), value as Answer])
    )
    return {
      ...base,
      kind: "single",
      choices: Object.keys(values).map((value) => ({ value, label: value })),
      reading: "choice",
      values,
    }
  }
  if (type === "boolean") {
    return {
      ...base,
      kind: "single",
      choices: [
        { value: "true", label: "Yes" },
        { value: "false", label: "No" },
      ],
      reading: "boolean",
    }
  }
  if (type === "array" && isRecord(schema.items) && schema.items.enum?.length) {
    const values = Object.fromEntries(
      schema.items.enum.map((value) => [String(value), value as Answer])
    )
    return {
      ...base,
      kind: "multiple",
      choices: Object.keys(values).map((value) => ({ value, label: value })),
      reading: "choice",
      values,
    }
  }
  if (type === "number" || type === "integer") {
    return {
      ...base,
      kind: "input",
      input: {
        type: "number",
        ...(schema.minimum !== undefined && { min: schema.minimum }),
        ...(schema.maximum !== undefined && { max: schema.maximum }),
        step: type === "integer" ? 1 : "any",
      },
      reading: type,
    }
  }
  if (type === "array") {
    return {
      ...base,
      kind: "input",
      input: { type: "text", placeholder: "Separate them with commas" },
      reading: "list",
    }
  }
  if (
    type === "object" ||
    (type === undefined && isRecord(schema.properties))
  ) {
    return {
      ...base,
      kind: "input",
      input: { type: "text", placeholder: "JSON" },
      reading: "json",
    }
  }
  return {
    ...base,
    kind: "input",
    input: {
      type: (schema.format && INPUT_FORMATS[schema.format]) || "text",
      placeholder: "Your answer",
    },
    reading: "string",
  }
}

/**
 * The form for an agent's question: a question per field of an object
 * schema (its `required` ones required), or one for any other schema, the
 * agent's `message` its title. No schema asks for text.
 */
export function askForm(schema: unknown, message: string): AskForm {
  const fields = isRecord(schema) ? schema.properties : undefined
  if (
    isRecord(schema) &&
    isRecord(fields) &&
    Object.keys(fields).length > 0 &&
    (typeOf(schema) ?? "object") === "object"
  ) {
    const required = new Set(
      Array.isArray(schema.required) ? schema.required.map(String) : []
    )
    return {
      fields: true,
      questions: Object.entries(fields).map(([name, field]) =>
        question(name, field, humanize(name), required.has(name))
      ),
    }
  }
  return {
    fields: false,
    questions: [question("answer", schema, message, true)],
  }
}

/** What the form's data holds: `FormData` or anything with its two reads. */
export type FormValues = {
  get(name: string): FormDataEntryValue | null
  getAll(name: string): FormDataEntryValue[]
}

const NOTHING = Symbol("nothing")

/** One question's answer in the schema's type; NOTHING when it's left empty. */
function read(question: Question, values: FormValues): Answer | typeof NOTHING {
  if (question.kind === "multiple") {
    const picked = values.getAll(question.name).map(String)
    if (!picked.length) return question.required ? [] : NOTHING
    return picked.map((value) => question.values?.[value] ?? value)
  }
  const raw = values.get(question.name)
  const text = typeof raw === "string" ? raw.trim() : ""
  if (!text) return NOTHING
  switch (question.reading) {
    case "choice":
      return question.values && text in question.values
        ? question.values[text]
        : text
    case "boolean":
      return text === "true"
    case "number": {
      const number = Number(text)
      return Number.isFinite(number) ? number : text
    }
    case "integer": {
      const number = Number(text)
      return Number.isInteger(number) ? number : text
    }
    case "list":
      return text
        .split(",")
        .map((each) => each.trim())
        .filter(Boolean)
    case "json":
      try {
        return JSON.parse(text) as Answer
      } catch {
        return text
      }
    default:
      return text
  }
}

/**
 * The answer to send: an object of the fields answered (those left empty
 * left out), or the one answer.
 */
export function answerFrom(form: AskForm, values: FormValues): Answer {
  if (!form.fields) {
    const answer = read(form.questions[0]!, values)
    return answer === NOTHING ? "" : answer
  }
  const answer: Record<string, Answer> = {}
  for (const question of form.questions) {
    const value = read(question, values)
    if (value !== NOTHING) answer[question.name] = value
  }
  return answer
}

const shown = (value: unknown): string =>
  value === true
    ? "Yes"
    : value === false
      ? "No"
      : Array.isArray(value)
        ? value.map(shown).join(", ")
        : isRecord(value)
          ? JSON.stringify(value)
          : String(value)

/** An answer in a line: "Environment: staging · Notify: Yes", or the answer itself. */
export function describeAnswer(answer: unknown, form: AskForm): string {
  if (form.fields && isRecord(answer)) {
    const titles = new Map(form.questions.map((q) => [q.name, q.title]))
    const parts = Object.entries(answer).map(([name, value]) => {
      const title = titles.get(name) ?? humanize(name)
      // A question needs no colon after its question mark.
      return `${title}${title.endsWith("?") ? "" : ":"} ${shown(value)}`
    })
    return parts.length ? parts.join(" · ") : "Nothing filled in"
  }
  return shown(answer)
}

