/**
 * The conversation and composer with the Forge and ADK parts: welcome, ADK
 * tool cards, agent labels, and the composer's context, model section,
 * context meter and `/` commands when they're configured. Render it inside
 * `AssistantProvider`.
 */
function AssistantThread() {
  const historyBlocked = useHistoryBlocked()
  const {
    commands,
    composerContext,
    composerLead,
    composerTrailingActions,
    messageMeta,
    followUps,
  } = useAssistantSettings()
  const hasCommands = Boolean(commands?.length)
  const hasContext = composerContext != null
  const components = React.useMemo(
    () => ({
      ...threadComponents,
      ...(hasContext && { ComposerHeader: AssistantComposerContext }),
      ...(composerLead && { ComposerLead: composerLead }),
      ...(composerTrailingActions && {
        ComposerTrailingActions: composerTrailingActions,
      }),
      // The model section, the context meter and the app's controls, each when it's on.
      ComposerActions: AssistantComposerActions,
      ...(hasCommands && { ComposerTriggers: AssistantCommandMenu }),
      ...(messageMeta && { MessageMeta: messageMeta }),
      // The agent server's follow-up questions, unless the app has its own.
      FollowUps: followUps ?? AdkFollowUps,
    }),
    [
      hasContext,
      hasCommands,
      messageMeta,
      followUps,
      composerLead,
      composerTrailingActions,
    ]
  )
  if (historyBlocked)
    return (
      <div className="h-full p-4">
        <AssistantHistoryStatus />
      </div>
    )
  return (
    <Thread
      components={components}
      placeholder={
        hasCommands ? "Send a message, or type / for commands..." : undefined
      }
    />
  )
}

export { AssistantProvider, AssistantThread }

import {
  CompositeAttachmentAdapter,
  SimpleImageAttachmentAdapter,
  SimpleTextAttachmentAdapter,
  type AttachmentAdapter,
  type CompleteAttachment,
  type PendingAttachment,
} from "@assistant-ui/react"

/*
 * What the composer's attach button takes, and how each file reaches an ADK
 * agent: images and documents as inline parts of the message, text files as
 * text. assistant-ui's own adapters do images and text; documents are below.
 */

/**
 * Documents ADK's model bridge sends on as files (to OpenAI through its
 * Files API), by type and by extension for browsers that leave the type out.
 */
const DOCUMENTS: Record<string, string> = {
  ".pdf": "application/pdf",
  ".doc": "application/msword",
  ".docx":
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  ".pptx":
    "application/vnd.openxmlformats-officedocument.presentationml.presentation",
}

/** The most a document may be: it travels in the message, as base64. */
export const MAX_DOCUMENT_BYTES = 10 * 1024 * 1024

const megabytes = (bytes: number) => `${(bytes / 1024 / 1024).toFixed(1)} MB`

function typeOf(file: File) {
  if (file.type) return file.type
  const name = file.name.toLowerCase()
  const extension = Object.keys(DOCUMENTS).find((ext) => name.endsWith(ext))
  return extension ? DOCUMENTS[extension] : "application/octet-stream"
}

/**
 * A type carrying the file's name, `application/pdf; name="report.pdf"`: ADK's
 * web client keeps only a part's type and data, both ways, so this is how the
 * chat still names the file when the conversation loads again. The agent
 * runtime gives the model the bare type (forge_common's AttachmentsPlugin).
 */
export const typeWithName = (type: string, name: string) =>
  `${type}; name="${name.replace(/[\r\n]+/g, " ").replace(/["\\]/g, "\\$&")}"`

function dataUrl(file: File, signal?: AbortSignal) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    const abort = () => reader.abort()
    signal?.addEventListener("abort", abort, { once: true })
    reader.onload = () => resolve(String(reader.result))
    reader.onerror = () => reject(reader.error)
    reader.onabort = () =>
      reject(signal?.reason ?? new DOMException("Aborted", "AbortError"))
    reader.onloadend = () => signal?.removeEventListener("abort", abort)
    reader.readAsDataURL(file)
  })
}

/** PDF, Word and PowerPoint files, sent whole as a file part of the message. */
export class DocumentAttachmentAdapter implements AttachmentAdapter {
  accept = [...Object.keys(DOCUMENTS), ...Object.values(DOCUMENTS)].join(",")

  async add({ file }: { file: File }): Promise<PendingAttachment> {
    if (file.size > MAX_DOCUMENT_BYTES)
      throw new Error(
        `${file.name} is ${megabytes(file.size)}: a document can be at most ${megabytes(MAX_DOCUMENT_BYTES)}.`
      )
    return {
      id: crypto.randomUUID(),
      type: "document",
      name: file.name,
      contentType: typeOf(file),
      file,
      status: { type: "requires-action", reason: "composer-send" },
    }
  }

  async send(
    attachment: PendingAttachment,
    options?: { signal?: AbortSignal }
  ): Promise<CompleteAttachment> {
    return {
      ...attachment,
      status: { type: "complete" },
      content: [
        {
          type: "file",
          data: await dataUrl(attachment.file, options?.signal),
          mimeType: typeWithName(
            attachment.contentType ?? typeOf(attachment.file),
            attachment.name
          ),
          filename: attachment.name,
        },
      ],
    }
  }

  async remove() {}
}

/** Images, text files and documents: what the composer takes by default. */
export const defaultAttachments = (): AttachmentAdapter =>
  new CompositeAttachmentAdapter([
    new SimpleImageAttachmentAdapter(),
    new SimpleTextAttachmentAdapter(),
    new DocumentAttachmentAdapter(),
  ])

import * as React from "react"
import {
  unstable_useSlashCommandAdapter,
  useAui,
  type AssistantClient,
  type Unstable_TriggerItem,
  type Unstable_TriggerMatcher,
} from "@assistant-ui/react"

import { ComposerTriggerPopover } from "@/components/assistant-ui/elements/composer-trigger-popover.aui"
import { Icon } from "@/components/forge/icon"
import type { IconProp } from "@/components/forge/icons"

import { useAssistantSettings } from "./assistant-context"

/**
 * A `/` command in the composer. What picking it does depends on its fields:
 *
 * - `execute`: runs in the app (start a conversation, open a sheet…); the
 *   typed `/command` is removed.
 * - `prompt`: fills the composer with the prompt, and sends it with `send`.
 * - neither: leaves `/id ` in the composer for the user to add arguments to,
 *   and the agent receives the command as text (handle it in its
 *   instructions).
 */
export type AssistantCommand = {
  /** Typed after the slash: `deploy` is `/deploy`. */
  id: string
  description?: string
  /** A Forge icon name or a Hugeicons glyph. */
  icon?: IconProp
  prompt?: string
  /** With `prompt`: send it straight away instead of leaving it to edit. */
  send?: boolean
  execute?: (aui: AssistantClient) => void
}

// Commands only open from a `/` at the very start of the message, so a path
// or a fraction later in the text never pops the menu.
const atStartOfMessage: Unstable_TriggerMatcher = (text, char, cursor) => {
  if (!text.startsWith(char)) return null
  const query = text.slice(char.length, cursor)
  return /\s/u.test(query) ? null : { query, offset: 0, endOffset: cursor }
}

function runCommand(command: AssistantCommand, aui: AssistantClient) {
  // The popover has removed the typed `/query` by now.
  const rest = aui.composer.getState().text.trimStart()
  if (command.execute) {
    command.execute(aui)
  } else if (command.prompt !== undefined) {
    aui.composer.setText(rest ? `${command.prompt} ${rest}` : command.prompt)
    if (command.send) aui.composer.send()
  } else {
    aui.composer.setText(`/${command.id} ${rest}`)
  }
}

// assistant-ui also matches descriptions; commands whose name starts with the
// query come first, then other name matches, then description matches.
const rank = (item: Unstable_TriggerItem, query: string) => {
  const id = item.id.toLowerCase()
  if (id.startsWith(query)) return 0
  return id.includes(query) ? 1 : 2
}

type TriggerAdapter = ReturnType<
  typeof unstable_useSlashCommandAdapter
>["adapter"]

function byName(adapter: TriggerAdapter): TriggerAdapter {
  return {
    ...adapter,
    search: (query) => {
      const lower = query.toLowerCase()
      return [...(adapter.search?.(query) ?? [])].sort(
        (a, b) => rank(a, lower) - rank(b, lower)
      )
    },
  }
}

type GlyphComponent = React.FC<{ className?: string }>

// One stable component per icon, so the popover's icon map never remounts.
const glyphs = new Map<IconProp, GlyphComponent>()
function glyphFor(icon: IconProp): GlyphComponent {
  let glyph = glyphs.get(icon)
  if (!glyph) {
    glyph = ({ className }) => <Icon icon={icon} className={className} />
    glyphs.set(icon, glyph)
  }
  return glyph
}

/**
 * The `/` command menu above the composer, for `AssistantScreen`'s
 * `commands`. Arrow keys move, Enter or Tab picks, Escape closes.
 */
function AssistantCommandMenu() {
  const { commands = [] } = useAssistantSettings()
  const aui = useAui()
  const slash = unstable_useSlashCommandAdapter({
    commands: commands.map((command) => ({
      id: command.id,
      description: command.description,
      icon: command.id,
      // The popover removes the typed `/query` as it calls this, and the
      // composer state reflects that from the next task.
      execute: () => setTimeout(() => runCommand(command, aui)),
    })),
    removeOnExecute: true,
  })
  const adapter = React.useMemo(() => byName(slash.adapter), [slash.adapter])
  const iconMap = React.useMemo(
    () =>
      Object.fromEntries(
        commands.flatMap((command) =>
          command.icon ? [[command.id, glyphFor(command.icon)]] : []
        )
      ),
    [commands]
  )

  return (
    <ComposerTriggerPopover
      char="/"
      matcher={atStartOfMessage}
      adapter={adapter}
      action={slash.action}
      iconMap={iconMap}
      emptyItemsLabel="No matching commands"
    />
  )
}

export { AssistantCommandMenu }

/**
 * How full an agent's context window is, as the agent server keeps it in the
 * ADK session's state (`forge:context:<agent>`, forge_common's
 * `ContextWindowPlugin`): what its conversation holds, what its model may
 * read, and where it's compacted. The composer's context meter shows it.
 */

/** The state key each agent's context window is kept under, before its name. */
export const CONTEXT_STATE_PREFIX = "forge:context:"

/** An agent's context window, as the agent server keeps it. */
export type AgentContext = {
  /** What its conversation holds: its last request, or once the model answered, that and the reply. */
  tokens: number
  /** What a request may hold: the model's window less what's kept for the reply. */
  limit: number
  /** Where it's compacted. */
  threshold: number
  /** The model's whole window, and of it what's kept for the reply. */
  window?: number
  reply?: number
  /** The threshold as a share of the limit, e.g. 0.8. */
  share?: number
  /** Whether it compacts at the threshold by itself; otherwise only when asked. */
  auto?: boolean
  /** `estimate`: measured before the request went out; `provider`: what the model reported. */
  counted?: "estimate" | "provider"
  /** The model that last answered it (`provider/model`). */
  model?: string
  compactions?: number
  lastCompaction?: {
    at?: number
    tokensBefore: number
    tokensAfter: number
  }
  /** A compaction was asked for, before its next request. */
  requested?: boolean
  /**
   * It works apart from the conversation (a task, an agent called as a tool,
   * a parallel branch): each call starts from what it was handed.
   */
  apart?: boolean
  /** When it was counted, in seconds since the epoch. */
  updated?: number
}

/** What a model may read, as the model list gives it. */
export type ModelWindow = {
  id: string
  name?: string
  contextWindow?: number
  maxTokens?: number
}

const isNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value)

/** One agent's entry, if it's one the server wrote. */
export function parseAgentContext(value: unknown): AgentContext | undefined {
  if (!value || typeof value !== "object") return undefined
  const raw = value as Record<string, unknown>
  if (!isNumber(raw.tokens) || !isNumber(raw.limit) || raw.limit <= 0) {
    return undefined
  }
  const last = raw.last_compaction as Record<string, unknown> | undefined
  return {
    tokens: raw.tokens,
    limit: raw.limit,
    threshold: isNumber(raw.threshold) ? raw.threshold : raw.limit,
    ...(isNumber(raw.window) && { window: raw.window }),
    ...(isNumber(raw.reply) && { reply: raw.reply }),
    ...(isNumber(raw.share) && { share: raw.share }),
    ...(typeof raw.auto === "boolean" && { auto: raw.auto }),
    ...((raw.counted === "estimate" || raw.counted === "provider") && {
      counted: raw.counted,
    }),
    ...(typeof raw.model === "string" && raw.model && { model: raw.model }),
    ...(isNumber(raw.compactions) && { compactions: raw.compactions }),
    ...(last &&
      isNumber(last.tokens_before) &&
      isNumber(last.tokens_after) && {
        lastCompaction: {
          tokensBefore: last.tokens_before,
          tokensAfter: last.tokens_after,
          ...(isNumber(last.at) && { at: last.at }),
        },
      }),
    ...(raw.requested === true && { requested: true }),
    ...(raw.apart === true && { apart: true }),
    ...(isNumber(raw.updated) && { updated: raw.updated }),
  }
}

/**
 * The agent whose context the composer shows: the conversation's own agent,
 * the one answering when it has an entry, else the one counted last. Agents
 * that work apart from it (a task the agent hands a question to) are left
 * out, since each of their calls starts afresh; only when there's no other
 * is the one counted last shown.
 */
export function currentContext(
  state: Readonly<Record<string, unknown>>,
  agent?: string
): { agent: string; context: AgentContext } | undefined {
  type Found = { agent: string; context: AgentContext }
  const later = (found: Found, than?: Found) =>
    !than || (found.context.updated ?? 0) > (than.context.updated ?? 0)
  let latest: Found | undefined
  let latestApart: Found | undefined
  for (const [key, value] of Object.entries(state)) {
    if (!key.startsWith(CONTEXT_STATE_PREFIX)) continue
    const context = parseAgentContext(value)
    if (!context) continue
    const found = { agent: key.slice(CONTEXT_STATE_PREFIX.length), context }
    if (context.apart) {
      if (later(found, latestApart)) latestApart = found
      continue
    }
    if (agent && found.agent === agent) return found
    if (later(found, latest)) latest = found
  }
  return latest ?? latestApart
}

/**
 * - `clear`: well below where it's compacted;
 * - `near`: within a tenth of it;
 * - `compacting`: past it, so it's compacted before the next request (or,
 *   when it only compacts when asked, would be);
 * - `full`: past what a request may hold.
 */
export type ContextPhase = "clear" | "near" | "compacting" | "full"

export type ContextView = {
  /** Tokens the conversation holds; 0 before the agent has been counted. */
  used: number
  /** What a request may hold. */
  limit: number
  /** Where it's compacted; unknown until the agent has been counted. */
  threshold?: number
  /** `used` and `threshold` as shares of the limit (0–1, `used` may pass 1). */
  usedShare: number
  thresholdShare?: number
  /** Before the limit, and before the compaction (negative once past). */
  left: number
  untilCompaction?: number
  phase: ContextPhase
  auto: boolean
  /** No count yet: the conversation hasn't reached the agent. */
  empty: boolean
  /** The count is an estimate (before a request) rather than the model's. */
  estimated: boolean
  /** The model whose window this is: the one chosen in the composer, else the one that answered. */
  model?: string
  window?: number
  reply?: number
  /** The model chosen in the composer isn't the one the count is from. */
  modelChanged: boolean
  compactions: number
  lastCompaction?: AgentContext["lastCompaction"]
  requested: boolean
}

/**
 * The meter's numbers. A model chosen in the composer (`model`) whose window
 * is known wins over the window the count was made against: the next request
 * runs on it, and the server compacts at the same share of its limit.
 */
export function contextView(
  context: AgentContext | undefined,
  model?: ModelWindow
): ContextView | undefined {
  const modelLimit =
    model && isNumber(model.contextWindow) && model.contextWindow > 0
      ? Math.max(1, model.contextWindow - (model.maxTokens ?? 0))
      : undefined
  if (!context && modelLimit === undefined) return undefined

  // The server's own numbers, unless the next request runs on another model.
  const switched =
    modelLimit !== undefined &&
    context?.model !== undefined &&
    context.model !== model?.id
  const fromModel = modelLimit !== undefined && (!context || switched)
  const limit = fromModel ? modelLimit : context!.limit
  const threshold = !context
    ? undefined
    : fromModel
      ? Math.max(
          1,
          Math.floor(
            limit * (context.share ?? context.threshold / context.limit)
          )
        )
      : context.threshold
  const used = context?.tokens ?? 0

  const phase: ContextPhase =
    used > limit
      ? "full"
      : threshold !== undefined && used >= threshold
        ? "compacting"
        : threshold !== undefined && used >= threshold * 0.9
          ? "near"
          : "clear"

  return {
    used,
    limit,
    ...(threshold !== undefined && {
      threshold,
      thresholdShare: threshold / limit,
      untilCompaction: threshold - used,
    }),
    usedShare: used / limit,
    left: limit - used,
    phase,
    auto: context?.auto ?? true,
    empty: context === undefined,
    estimated: context?.counted === "estimate",
    ...(fromModel
      ? {
          model: model?.name ?? model?.id,
          window: model?.contextWindow,
          reply: model?.maxTokens,
        }
      : {
          // The model that answered, by its name when it's the one chosen.
          ...(context?.model && {
            model:
              model?.id === context.model
                ? (model.name ?? context.model)
                : context.model,
          }),
          ...(context?.window !== undefined && { window: context.window }),
          ...(context?.reply !== undefined && { reply: context.reply }),
        }),
    modelChanged: switched,
    compactions: context?.compactions ?? 0,
    ...(context?.lastCompaction && { lastCompaction: context.lastCompaction }),
    requested: context?.requested ?? false,
  }
}

const compactFormat = new Intl.NumberFormat("en", {
  notation: "compact",
  maximumFractionDigits: 1,
})
const fullFormat = new Intl.NumberFormat("en")

/** Tokens in a few characters: 950, 152.3K, 1.2M. */
export const compactTokens = (tokens: number) =>
  compactFormat.format(Math.max(0, Math.round(tokens)))

/** Tokens in full: 152,340. */
export const fullTokens = (tokens: number) =>
  fullFormat.format(Math.round(tokens))

/** A share as a whole percentage, at least 1% once anything is used. */
export function percent(share: number) {
  if (share <= 0) return "0%"
  return `${Math.max(1, Math.round(share * 100))}%`
}

/**
 * Follow-up questions after a reply, written by the agent server: a run asks
 * for them in its state (`forge:suggest_follow_ups`, which `useAdkAssistant`
 * sends with `suggestFollowUps`), and the server keeps the last reply's in the
 * ADK session's state (`forge:follow_ups`, forge_common's `FollowUpsPlugin`),
 * which the thread shows above the composer.
 */

/** The state key a run asks for follow-ups with: true, or `{ count }`. */
export const FOLLOW_UPS_REQUEST_KEY = "forge:suggest_follow_ups"

/** The state key the last reply's follow-ups are kept under: `{ suggestions }`. */
export const FOLLOW_UPS_STATE_KEY = "forge:follow_ups"

/** The most follow-ups a run may ask for. */
export const MOST_FOLLOW_UPS = 5

/**
 * Whether runs ask for follow-up questions after the reply: true for the
 * server's default number (3), or how many (1–5).
 */
export type FollowUpsOption = boolean | { count?: number }

/** What a run sends for `option`: nothing when it's off. */
export function followUpsRequest(
  option: FollowUpsOption | undefined
): Record<string, unknown> | undefined {
  if (!option) return undefined
  if (option === true || option.count === undefined) {
    return { [FOLLOW_UPS_REQUEST_KEY]: true }
  }
  const count = Math.round(option.count)
  return {
    [FOLLOW_UPS_REQUEST_KEY]: {
      count: Math.min(
        Math.max(Number.isFinite(count) ? count : 1, 1),
        MOST_FOLLOW_UPS
      ),
    },
  }
}

/** The last reply's follow-ups in the session's state; none when it has none. */
export function followUpsOf(
  state: Readonly<Record<string, unknown>>
): string[] {
  const kept = state[FOLLOW_UPS_STATE_KEY]
  if (typeof kept !== "object" || kept === null) return []
  const { suggestions } = kept as { suggestions?: unknown }
  if (!Array.isArray(suggestions)) return []
  return suggestions.filter(
    (each): each is string => typeof each === "string" && each.trim() !== ""
  )
}

import { createContext, useContext, useSyncExternalStore } from "react"
import { useAuiState, type AssistantRuntime } from "@assistant-ui/react"
import type { HistoryFeedback, HistoryFeedbackState } from "./history-feedback"

export const HistoryContext = createContext<
  { runtime: AssistantRuntime; feedback?: HistoryFeedback } | undefined
>(undefined)
const EMPTY: HistoryFeedbackState = { entries: new Map() }
const emptySnapshot = () => EMPTY
const noSubscription = () => () => {}

export function useHistoryFeedback() {
  const context = useContext(HistoryContext)
  const feedback = context?.feedback
  const state = useSyncExternalStore(
    feedback?.subscribe ?? noSubscription,
    feedback?.getSnapshot ?? emptySnapshot,
    feedback?.getSnapshot ?? emptySnapshot
  )
  const id = useAuiState((s) => {
    const current = s.threads.threadItems.find(
      (item) => item.id === s.threads.mainThreadId
    )
    return current?.externalId ?? current?.remoteId
  })
  return { ...context, state, entry: id ? state.entries.get(id) : undefined }
}

export function useHistoryBlocked() {
  const { entry } = useHistoryFeedback()
  return Boolean(entry?.error && !entry.loaded)
}

import type {
  AssistantRuntime,
  RemoteThreadListAdapter,
} from "@assistant-ui/react"
import type { UseAdkRuntimeOptions } from "@assistant-ui/react-google-adk"

export type HistoryLoader = NonNullable<UseAdkRuntimeOptions["load"]>
export type HistoryEntry = {
  loading: boolean
  loaded: boolean
  error?: string
}
export type HistoryFeedbackState = {
  entries: ReadonlyMap<string, HistoryEntry>
  navigation?: { id: string; error: string }
}
const EMPTY: HistoryFeedbackState = { entries: new Map() }

/** Give people an actionable explanation without rendering raw server responses. */
export function historyErrorMessage(
  error: unknown,
  operation: "list" | "load" | "open"
) {
  const status =
    typeof error === "object" && error !== null && "status" in error
      ? Number(error.status)
      : Number(
          error instanceof Error
            ? error.message.match(/:\s*(\d{3})\b/)?.[1]
            : NaN
        )
  if (status === 401)
    return "Your session has expired. Sign in again, then retry."
  if (status === 403)
    return "You don't have permission to view this conversation history."
  if (status === 404 && operation !== "list")
    return "This conversation is no longer available. You can start a new conversation."
  return operation === "list"
    ? "Your conversations couldn't be loaded. Check your connection and retry."
    : operation === "open"
      ? "That conversation couldn't be opened. Check your connection and retry."
      : "This conversation couldn't be loaded. Check your connection and retry before sending another message."
}

/** Per-connection feedback, kept outside agent state and scoped to each conversation. */
export function createHistoryFeedback() {
  let state = EMPTY
  const listeners = new Set<() => void>()
  const requests = new Map<string, symbol>()
  let navigation = 0
  let selected: string | undefined
  const publish = (next: HistoryFeedbackState) => {
    state = next
    for (const listener of listeners) listener()
  }
  const entry = (id: string, value: HistoryEntry | undefined) => {
    const entries = new Map(state.entries)
    if (value) entries.set(id, value)
    else entries.delete(id)
    publish({ ...state, entries })
  }
  return {
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    getSnapshot: () => state,
    select(id: string | undefined) {
      if (selected === id) return
      selected = id
      navigation++
      if (state.navigation) publish({ ...state, navigation: undefined })
    },
    assertReady(id: string | undefined) {
      const current = id ? state.entries.get(id) : undefined
      if (current && !current.loaded)
        throw new Error(
          "Load this conversation successfully before sending another message. Retry loading it or start a new conversation."
        )
    },
    wrapLoad(load: HistoryLoader): HistoryLoader {
      return async (id, options) => {
        if (options?.signal?.aborted)
          throw (
            options.signal.reason ?? new DOMException("Aborted", "AbortError")
          )
        const previous = state.entries.get(id)
        const token = Symbol(id)
        requests.set(id, token)
        entry(id, {
          ...previous,
          loaded: previous?.loaded ?? false,
          loading: true,
        })
        try {
          const snapshot = await load(id, options)
          if (!options?.signal?.aborted && requests.get(id) === token)
            entry(id, { loaded: true, loading: false })
          return snapshot
        } catch (error) {
          if (!options?.signal?.aborted && requests.get(id) === token)
            entry(id, {
              loaded: previous?.loaded ?? false,
              loading: false,
              error: historyErrorMessage(error, "load"),
            })
          throw error
        } finally {
          if (requests.get(id) === token) {
            requests.delete(id)
            if (options?.signal?.aborted)
              entry(
                id,
                previous?.loaded || previous?.error
                  ? { ...previous, loading: false }
                  : undefined
              )
          }
        }
      }
    },
    wrapAdapter(adapter: RemoteThreadListAdapter): RemoteThreadListAdapter {
      return {
        ...adapter,
        async fetch(id) {
          const token = ++navigation
          if (state.navigation) publish({ ...state, navigation: undefined })
          try {
            return await adapter.fetch(id)
          } catch (error) {
            if (token === navigation)
              publish({
                ...state,
                navigation: { id, error: historyErrorMessage(error, "open") },
              })
            throw error
          }
        },
      }
    },
  }
}
export type HistoryFeedback = ReturnType<typeof createHistoryFeedback>

// The hook and provider share feedback by runtime, so every existing screen,
// modal and custom layout receives it without an additional required prop.
const registered = new WeakMap<AssistantRuntime, HistoryFeedback>()
const registryListeners = new Set<() => void>()
export const historyForRuntime = (runtime: AssistantRuntime) =>
  registered.get(runtime)
export function subscribeHistoryRegistry(listener: () => void) {
  registryListeners.add(listener)
  return () => {
    registryListeners.delete(listener)
  }
}
export function registerHistoryFeedback(
  runtime: AssistantRuntime,
  feedback: HistoryFeedback
) {
  registered.set(runtime, feedback)
  for (const listener of registryListeners) listener()
  const select = () => {
    const current = runtime.threads.mainItem.getState()
    feedback.select(current.externalId ?? current.remoteId)
  }
  select()
  const unsubscribe = runtime.threads.subscribe(select)
  return () => {
    unsubscribe()
    if (registered.get(runtime) === feedback) {
      registered.delete(runtime)
      for (const listener of registryListeners) listener()
    }
  }
}

import {
  AdkEventAccumulator,
  type AdkEvent,
  type AdkMessage,
  type AdkThreadSnapshot,
} from "@assistant-ui/react-google-adk"

import {
  CLIENT_TURN_STATE_KEY,
  TURN_METADATA_KEY,
  adkEventFailure,
  adkEventsForDisplay,
  clientTurnOutcome,
  normalizeAdkEvent,
  type ClientTurnOutcome,
} from "./turn-lifecycle.ts"

const record = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

/** Reject malformed history atomically; a partly replayed session looks believable but is wrong. */
function parseEvent(value: unknown, index: number): AdkEvent {
  const invalid = (field: string) => {
    throw new Error(`Invalid ADK session event at index ${index}: ${field}.`)
  }
  if (!record(value) || !Object.keys(value).length)
    return invalid("expected a non-empty object")
  const id = value.id
  if (
    id != null &&
    typeof id !== "string" &&
    !(typeof id === "number" && Number.isFinite(id))
  )
    return invalid('expected "id" to be a string or finite number')
  for (const key of [
    "author",
    "invocationId",
    "invocation_id",
    "errorCode",
    "error_code",
    "errorMessage",
    "error_message",
    "finishReason",
    "finish_reason",
  ])
    if (value[key] != null && typeof value[key] !== "string")
      return invalid(`expected "${key}" to be a string`)
  for (const key of ["partial", "interrupted", "turnComplete", "turn_complete"])
    if (value[key] != null && typeof value[key] !== "boolean")
      return invalid(`expected "${key}" to be a boolean`)
  for (const key of ["actions", "customMetadata", "custom_metadata"])
    if (value[key] != null && !record(value[key]))
      return invalid(`expected "${key}" to be an object`)
  if (record(value.actions))
    for (const key of [
      "stateDelta",
      "state_delta",
      "artifactDelta",
      "artifact_delta",
    ])
      if (value.actions[key] != null && !record(value.actions[key]))
        return invalid(`expected "actions.${key}" to be an object`)
  const content = value.content
  if (content != null) {
    if (!record(content)) return invalid('expected "content" to be an object')
    if (content.parts != null) {
      if (!Array.isArray(content.parts) || !content.parts.every(record))
        return invalid('expected "content.parts" to be an array of objects')
      for (const part of content.parts) {
        if (part.text != null && typeof part.text !== "string")
          return invalid('expected part "text" to be a string')
        for (const key of [
          "functionCall",
          "function_call",
          "functionResponse",
          "function_response",
          "inlineData",
          "inline_data",
          "fileData",
          "file_data",
        ])
          if (part[key] != null && !record(part[key]))
            return invalid(`expected part "${key}" to be an object`)
      }
    }
  }
  return normalizeAdkEvent({
    ...value,
    id: id == null ? `history-event-${index}` : String(id),
    ...(typeof value.error === "string" &&
      value.errorMessage == null &&
      value.error_message == null && { errorMessage: value.error }),
  } as AdkEvent)
}

/** The SDK joins adjacent AI/tool messages using the first AI status only. */
function preserveIncompleteStatuses(messages: AdkMessage[]): AdkMessage[] {
  const result = [...messages]
  let group: number[] = []
  const finish = () => {
    const messages = group.map((index) => result[index])
    const failed =
      messages.find(
        (message) =>
          message?.type === "ai" &&
          message.status?.type === "incomplete" &&
          ["error", "length", "content-filter"].includes(message.status.reason)
      ) ??
      messages.find(
        (message) =>
          message?.type === "ai" &&
          message.status?.type === "incomplete" &&
          message.status.reason === "cancelled"
      )
    if (failed?.type === "ai")
      for (const index of group) {
        const message = result[index]
        if (message?.type === "ai")
          result[index] = { ...message, status: failed.status }
      }
    group = []
  }
  for (const [index, message] of result.entries()) {
    if (message.type === "human") finish()
    else if (message.type === "ai") group.push(index)
  }
  finish()
  return result
}

/** Cleanup can append a control-only outcome after a newer turn has already run. */
function placeTerminalOutcomes(events: AdkEvent[]): AdkEvent[] {
  const lastInvocationEvent = new Map<string, number>()
  const after = new Map<number, AdkEvent[]>()
  const moved = new Set<number>()
  for (const [index, event] of events.entries()) {
    const metadata = event.customMetadata
    const terminal = clientTurnOutcome(metadata?.[TURN_METADATA_KEY])
    const hasActions = Object.values(event.actions ?? {}).some((value) =>
      record(value)
        ? Object.keys(value).length > 0
        : Array.isArray(value)
          ? value.length > 0
          : Boolean(value)
    )
    const controlOnly =
      terminal &&
      terminal.status !== "running" &&
      Object.keys(metadata ?? {}).every((key) => key === TURN_METADATA_KEY) &&
      !event.content?.parts?.length &&
      !event.errorCode &&
      !event.errorMessage &&
      !event.finishReason &&
      !event.interrupted &&
      !hasActions &&
      event.author !== "user"
    const id = event.invocationId
    if (controlOnly) {
      const prior = id ? lastInvocationEvent.get(id) : undefined
      if (prior !== undefined) {
        const outcomes = after.get(prior) ?? []
        outcomes.push(event)
        after.set(prior, outcomes)
        moved.add(index)
      }
      continue
    }
    if (id) lastInvocationEvent.set(id, index)
  }
  // Only relocate control envelopes with an exact, earlier invocation match.
  // Content/state events keep their original order; timestamps are never used.
  return events.flatMap((event, index) => [
    ...(moved.has(index) ? [] : [event]),
    ...(after.get(index) ?? []),
  ])
}

/** Reconstruct all ADK state, preserving failed response text and the last turn's outcome. */
export function snapshotOfAdkEvents(
  events: readonly unknown[]
): AdkThreadSnapshot {
  if (!Array.isArray(events))
    throw new Error("Invalid ADK session history: expected an array of events.")
  const parsed = placeTerminalOutcomes(events.map(parseEvent))
  const accumulator = new AdkEventAccumulator()
  let invocationId: string | undefined
  let outcome: ClientTurnOutcome = { status: "succeeded" }
  for (const event of parsed) {
    const incomingId = event.invocationId
    // User events also delimit turns in older histories lacking invocation IDs.
    if (
      event.author === "user" ||
      (incomingId && incomingId !== invocationId)
    ) {
      outcome = { status: "succeeded" }
      invocationId = incomingId
    }
    if (incomingId) invocationId = incomingId
    for (const displayed of adkEventsForDisplay(event))
      accumulator.processEvent(displayed)
    const failure = adkEventFailure(event)
    const terminal = clientTurnOutcome(
      event.customMetadata?.[TURN_METADATA_KEY]
    )
    if (failure) {
      outcome = { status: "failed", ...failure }
      // Contentless filter/length stops otherwise produce no assistant reply.
      if (!event.errorCode && !event.errorMessage)
        accumulator.processEvent({ id: `${event.id}:failure`, ...failure })
    } else if (outcome.status !== "failed") {
      if (terminal?.status === "failed") {
        outcome = terminal
        accumulator.processEvent({
          id: `${event.id}:failure`,
          errorCode: terminal.errorCode ?? "AGENT_ERROR",
          errorMessage:
            terminal.errorMessage ??
            "The assistant couldn't finish this reply. Please try again.",
        })
      } else if (terminal?.status === "cancelled" || event.interrupted) {
        const message =
          terminal?.errorMessage ||
          "The reply was stopped before it finished. Please try again."
        if (outcome.status !== "cancelled") {
          // Keep the stop explanation on this turn after a later turn clears
          // the latest-outcome banner. Finalize first so it cannot replace text.
          accumulator.processEvent({
            id: `${event.id}:stop`,
            interrupted: true,
          })
          accumulator.processEvent({
            id: `${event.id}:notice`,
            partial: true,
            content: { parts: [{ text: message }] },
          })
          accumulator.processEvent({
            id: `${event.id}:stopped`,
            interrupted: true,
          })
        }
        outcome = { ...terminal, status: "cancelled", errorMessage: message }
      }
    }
  }
  return {
    messages: preserveIncompleteStatuses(accumulator.getMessages()),
    longRunningToolIds: accumulator.getLongRunningToolIds(),
    toolConfirmations: accumulator.getToolConfirmations(),
    authRequests: accumulator.getAuthRequests(),
    escalated: accumulator.isEscalated(),
    messageMetadata: accumulator.getMessageMetadata(),
    stateDelta: {
      ...accumulator.getStateDelta(),
      [CLIENT_TURN_STATE_KEY]: outcome,
    },
    artifactDelta: accumulator.getArtifactDelta(),
    agentInfo: accumulator.getAgentInfo(),
  }
}

type Headers =
  | Record<string, string>
  | (() => Record<string, string> | Promise<Record<string, string>>)

async function requestHeaders(
  headers: Headers | undefined,
  signal?: AbortSignal
): Promise<Record<string, string>> {
  signal?.throwIfAborted()
  if (typeof headers !== "function") return headers ?? {}
  if (!signal) return headers()
  return new Promise((resolve, reject) => {
    const abort = () => reject(signal.reason)
    signal.addEventListener("abort", abort, { once: true })
    Promise.resolve()
      .then(headers)
      .then(resolve, reject)
      .finally(() => signal.removeEventListener("abort", abort))
  })
}

/** Session loader used by every live ADK chat; headers are read afresh per request. */
export function createAdkHistoryLoader({
  url,
  appName,
  userId,
  headers,
}: {
  url: string
  appName: string
  userId: string
  headers?: Headers
}) {
  const base = `${url.replace(/\/+$/, "")}/apps/${encodeURIComponent(appName)}/users/${encodeURIComponent(userId)}/sessions`
  return async (
    sessionId: string,
    options?: { signal?: AbortSignal }
  ): Promise<AdkThreadSnapshot> => {
    const signal = options?.signal
    const resolved = await requestHeaders(headers, signal)
    signal?.throwIfAborted()
    const response = await fetch(`${base}/${encodeURIComponent(sessionId)}`, {
      headers: resolved,
      signal,
    })
    if (!response.ok)
      throw new Error(`Failed to load conversation: ${response.status}`)
    const session: unknown = await response.json()
    signal?.throwIfAborted()
    if (
      !record(session) ||
      typeof session.id !== "string" ||
      !session.id ||
      session.id !== sessionId
    )
      throw new Error(
        'Invalid ADK session load response: expected the requested session "id".'
      )
    if (session.events !== undefined && !Array.isArray(session.events))
      throw new Error(
        'Invalid ADK session load response: expected "events" to be an array.'
      )
    return snapshotOfAdkEvents(session.events ?? [])
  }
}

import { useState, useSyncExternalStore, type ReactNode } from "react"
import { useAuiState, type AssistantRuntime } from "@assistant-ui/react"
import { Button } from "@/components/ui/button"
import {
  historyErrorMessage,
  historyForRuntime,
  subscribeHistoryRegistry,
} from "./history-feedback"
import { HistoryContext, useHistoryFeedback } from "./history-context"

export function AssistantHistoryProvider({
  runtime,
  children,
}: {
  runtime: AssistantRuntime
  children: ReactNode
}) {
  const feedback = useSyncExternalStore(
    subscribeHistoryRegistry,
    () => historyForRuntime(runtime),
    () => historyForRuntime(runtime)
  )
  return (
    <HistoryContext.Provider value={{ runtime, feedback }}>
      {children}
    </HistoryContext.Provider>
  )
}

/** Available even in a chat page with its history sidebar hidden. */
export function AssistantHistoryStatus() {
  const { runtime, entry, state } = useHistoryFeedback()
  const listError = useAuiState((s) => s.threads.loadError)
  const listLoading = useAuiState((s) => s.threads.isLoading)
  const [retrying, setRetrying] = useState<unknown>()
  const [actionError, setActionError] = useState<{
    source: unknown
    message: string
  }>()
  // Async actions belong to the error they started from. A conversation switch
  // or a newer load failure must never inherit an older action's feedback.
  const source = entry?.error ? entry : (state.navigation ?? listError)
  const error =
    entry?.error ??
    state.navigation?.error ??
    (listError ? historyErrorMessage(listError, "list") : undefined)
  if (!runtime || !error) return null
  const busy = retrying === source || Boolean(entry?.loading) || listLoading
  const retry = async () => {
    setRetrying(source)
    setActionError(undefined)
    try {
      if (entry?.error) await runtime.threads.reloadMainThread()
      else if (state.navigation)
        await runtime.threads.switchToThread(state.navigation.id)
      else await runtime.threads.reload()
    } catch (error) {
      // Load/fetch wrappers retain the scoped error. Also cover failures of
      // the runtime action itself rather than leaving an unhandled promise.
      setActionError({
        source,
        message: historyErrorMessage(
          error,
          entry?.error ? "load" : state.navigation ? "open" : "list"
        ),
      })
    } finally {
      setRetrying((current: unknown) =>
        current === source ? undefined : current
      )
    }
  }
  const newConversation = async () => {
    try {
      await runtime.threads.switchToNewThread()
    } catch (error) {
      setActionError({ source, message: historyErrorMessage(error, "open") })
    }
  }
  return (
    <div
      role="alert"
      data-slot="assistant-history-error"
      className="mx-2 rounded-(--radius-card) border border-danger-border bg-danger-surface p-3 text-xs text-danger-foreground"
    >
      <p className="font-medium">
        {entry?.error
          ? "Conversation couldn't load"
          : state.navigation
            ? "Conversation couldn't open"
            : "Conversation list couldn't load"}
      </p>
      <p className="mt-1 leading-relaxed">
        {actionError && actionError.source === source
          ? actionError.message
          : error}
      </p>
      <div className="mt-3 flex gap-2">
        <Button
          size="sm"
          variant="outline"
          disabled={busy}
          onClick={() => {
            void retry()
          }}
        >
          {busy ? "Retrying…" : "Retry"}
        </Button>
        {entry?.error && !entry.loaded && (
          <Button
            size="sm"
            variant="ghost"
            disabled={busy}
            onClick={() => {
              void newConversation()
            }}
          >
            New conversation
          </Button>
        )}
      </div>
    </div>
  )
}

import type {
  AssistantSearch,
  AssistantSource,
  AssistantSourcesConfig,
} from "./sources"

/*
 * Citations from Forge's knowledge base searches: a chat agent's knowledge
 * base tool (forge_agent_runtime's KnowledgeBaseTool) and the Forge
 * assistant's search_knowledge_bases answer
 *
 *   { status: "success",
 *     payload: { searched: ["Claims knowledge"],
 *                passages: [{ ref, knowledge_base, knowledge_base_id, document,
 *                             document_id, section, location, text, score }],
 *                organization_id?, note? } }
 *
 * (Forge's tools answer in that envelope; a bare payload reads too), and the
 * agent cites passages by ref ("[KQM4821]"). A chat agent's tool is named
 * whatever its builder called it, so a result is recognised by its shape,
 * not its name.
 */

/** One passage of a knowledge base tool's result. */
export type KnowledgePassage = {
  /** What the answer cites it by, e.g. "KQM4821". */
  ref: string
  /** The name of the knowledge base it's in. */
  knowledge_base?: string
  knowledge_base_id?: string
  /** The document's name, e.g. its filename. */
  document?: string
  document_id?: string
  /** The headings it's under: "Appeals > Denied claims". */
  section?: string
  /** Where in the document: "page 4", "slide 3: Pricing". */
  location?: string
  text?: string
  /** How relevant it is; higher is better. */
  score?: number
  /**
   * The organization whose knowledge base it is, when the search says
   * (the Forge assistant's does): for a link to the document.
   */
  organization_id?: string
}

export type KnowledgeSourcesOptions = {
  /**
   * Where a passage's document opens (the "Open document" link), e.g. its
   * knowledge base's page in Forge with it open; no link without.
   */
  documentHref?: (passage: KnowledgePassage) => string | undefined
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

/**
 * A result as ADK delivers it: a value or JSON text, sometimes wrapped as
 * `{ result }`; a Forge tool's in `{ status: "success", payload }`.
 */
function readResult(result: unknown): Record<string, unknown> | undefined {
  let value = result
  if (typeof value === "string") {
    try {
      value = JSON.parse(value)
    } catch {
      return undefined
    }
  }
  if (
    isObject(value) &&
    isObject(value.result) &&
    Object.keys(value).length === 1
  )
    value = value.result
  if (isObject(value) && value.status === "success" && isObject(value.payload))
    value = value.payload
  return isObject(value) ? value : undefined
}

type KnowledgeResult = { searched: string[]; passages: KnowledgePassage[] }

/** A knowledge base search's result; undefined for any other tool's. */
function knowledgeResult(result: unknown): KnowledgeResult | undefined {
  const value = readResult(result)
  if (!value || !Array.isArray(value.passages)) return undefined
  const organization =
    typeof value.organization_id === "string"
      ? value.organization_id
      : undefined
  const passages = value.passages
    .filter(
      (p): p is KnowledgePassage => isObject(p) && typeof p.ref === "string"
    )
    .map((p) => ({ organization_id: organization, ...p }))
  const searched = Array.isArray(value.searched)
    ? value.searched.filter((name): name is string => typeof name === "string")
    : []
  return { searched, passages }
}

/** Identifies a passage's document: two knowledge bases can hold the same filename. */
const documentKey = (passage: KnowledgePassage) =>
  passage.document_id ||
  `${passage.knowledge_base_id ?? passage.knowledge_base ?? ""}/${passage.document ?? ""}`

/**
 * Where in its document a passage is: "Refunds > Eligibility (page 2)". The
 * sources list joins a document's passages with " · ", so one passage's
 * parts don't.
 */
function where({ section, location }: KnowledgePassage): string | undefined {
  if (section && location) return `${section} (${location})`
  return section || location || undefined
}

/**
 * The sources config for agents with Forge knowledge base tools: each
 * passage a search found becomes a source the answer can cite, grouped by
 * document, from the knowledge base named under it; each search call's card
 * says what it searched and found.
 *
 * ```tsx
 * const sources = knowledgeBaseSources()  // once, at module scope
 * <AssistantScreen runtime={runtime} sources={sources} />
 * ```
 */
export function knowledgeBaseSources(
  options: KnowledgeSourcesOptions = {}
): AssistantSourcesConfig {
  return {
    fromToolCall: (_toolName, result) =>
      (knowledgeResult(result)?.passages ?? []).map(
        (passage): AssistantSource => ({
          ref: passage.ref,
          document: {
            key: documentKey(passage),
            title: passage.document || "Untitled document",
            subtitle: passage.knowledge_base || undefined,
            href: options.documentHref?.(passage),
          },
          location: where(passage),
          excerpt: passage.text || undefined,
        })
      ),
    searchOf: (_toolName, result): AssistantSearch | undefined => {
      const found = knowledgeResult(result)
      if (!found) return undefined
      return {
        searched: found.searched,
        found: found.passages.length,
        documents: new Set(found.passages.map(documentKey)).size,
      }
    },
  }
}

import type { IconProp } from "@/components/forge/icons"

/** A model the agent can run on, picked from the composer's model section. */
export type AssistantModel = {
  /** Sent to the agent, e.g. "gemini-2.5-pro". */
  id: string
  name: string
  description?: string
  /**
   * Models with the same group are listed together under it, e.g. their
   * provider ("OpenAI"), in the order the groups first appear.
   */
  group?: string
  /** Shown before its name, e.g. its maker's mark. */
  icon?: IconProp
  /**
   * The ids of the thinking levels it offers, e.g. `["off"]` for a model
   * that doesn't reason. Default: every level of the model section.
   */
  thinkingLevels?: string[]
  /**
   * Its context window, and of it the most one reply may take, in tokens:
   * the context meter measures against them while it's the one chosen.
   */
  contextWindow?: number
  maxTokens?: number
}

/** How long the model thinks before it answers. */
export type ThinkingLevel = {
  /** Sent to the agent, e.g. "high". */
  id: string
  label: string
  description?: string
}

export const defaultThinkingLevels: ThinkingLevel[] = [
