  { id: "low", label: "Low", description: "A quick plan first" },
  { id: "medium", label: "Medium", description: "Balanced for most work" },
  {
    id: "high",
    label: "High",
    description: "Longest reasoning, for hard problems",
  },
]

/**
 * Every level a model provider configuration knows (model_provider.yaml, as
 * the coding agent and the Forge agent read it), from least to most thinking.
 * Pass it as `thinkingLevels` with models that say which they offer.
 */
export const extendedThinkingLevels: ThinkingLevel[] = [
  { id: "off", label: "Off", description: "Answer straight away" },
  { id: "minimal", label: "Minimal", description: "The briefest look first" },
  { id: "low", label: "Low", description: "A quick plan first" },
  { id: "medium", label: "Medium", description: "Balanced for most work" },
  {
    id: "high",
    label: "High",
    description: "Long reasoning, for hard problems",
  },
  {
    id: "xhigh",
    label: "Extra high",
    description: "Longest reasoning, for the hardest problems",
  },
]

/**
 * The level a model runs at when `id` is chosen: that one if it's among
 * `levels`, else the nearest above it in `order`, else the nearest below,
 * else the first. The same rule the server applies.
 */
export function nearestThinkingLevel(
  levels: ThinkingLevel[],
  order: ThinkingLevel[],
  id: string
): string | undefined {
  if (levels.some((level) => level.id === id)) return id
  const offered = new Set(levels.map((level) => level.id))
  const index = order.findIndex((level) => level.id === id)
  if (index >= 0) {
    const above = order.slice(index + 1).find((level) => offered.has(level.id))
    if (above) return above.id
    const below = order
      .slice(0, index)
      .reverse()
      .find((level) => offered.has(level.id))
    if (below) return below.id
  }
  return levels[0]?.id
}

/** What the model section has selected, sent with every run. */
export type ModelSelection = {
  model: string | undefined
  thinkingLevel: string
}

/**
 * The model section's choices and selection, from `useAdkAssistant`. Pass it
 * to `AssistantScreen` with `showModels`.
 */
export type ModelSettings = ModelSelection & {
  models: AssistantModel[]
  /** The selected model's levels. */
  thinkingLevels: ThinkingLevel[]
  setModel: (id: string) => void
  setThinkingLevel: (id: string) => void
  /**
   * Called by the model section while it's mounted: the selection is only
   * sent while someone can see it. Returns the cleanup.
   */
  show: () => () => void
}

/** The default ADK state delta: `model` and `thinking_level` session keys. */
export const defaultModelStateDelta = ({
  model,
  thinkingLevel,
}: ModelSelection): Record<string, unknown> => ({
  ...(model && { model }),
  thinking_level: thinkingLevel,
})

import type { createAdkSessionAdapter } from "@assistant-ui/react-google-adk"

type SessionAdapter = ReturnType<typeof createAdkSessionAdapter>["adapter"]

/**
 * Where a conversation keeps its title in its ADK session's state. Forge's
 * agent servers write it with the conversation's first turn
 * (`forge_common.adk.titles`); other ADK servers don't, and their
 * conversations stay untitled.
 */
export const TITLE_KEY = "forge:title"

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

/** A session's title, from its state; undefined without one. */
export function titleOf(session: unknown): string | undefined {
  const state = isRecord(session) ? session.state : undefined
  const title = isRecord(state) ? state[TITLE_KEY] : undefined
  return typeof title === "string" && title.trim() ? title.trim() : undefined
}

const idOf = (session: unknown) =>
  isRecord(session) && typeof session.id === "string" && session.id
    ? session.id
    : undefined

/**
 * The ADK session adapter, listing each conversation with its title: the
 * package's lists them untitled (ADK sessions have no title of their own),
 * so every conversation read "New conversation" after a reload. A thread's
 * title is still named in the browser as it starts (`AutoTitle`); the server
 * keeps the same one with its first turn.
 */
export function withSessionTitles(
  adapter: SessionAdapter,
  {
    url,
    appName,
    userId,
    headers,
  }: {
    url: string
    appName: string
    userId: string
    headers: () => Record<string, string>
  }
): SessionAdapter {
  const base = `${url.replace(/\/+$/, "")}/apps/${encodeURIComponent(appName)}/users/${encodeURIComponent(userId)}/sessions`
  return {
    ...adapter,
    async list() {
      const res = await fetch(base, { headers: headers() })
      if (!res.ok) throw new Error(`Failed to list sessions: ${res.status}`)
      const sessions: unknown = await res.json()
      if (!Array.isArray(sessions))
        throw new Error(
          "Invalid ADK session list response: expected an array of sessions."
        )
      return {
        threads: sessions.map((session) => {
          const id = idOf(session)
          if (!id)
            throw new Error(
              "Invalid ADK session list response: a conversation has no ID."
            )
          return {
            status: "regular" as const,
            remoteId: id,
            externalId: id,
            title: titleOf(session),
          }
        }),
      }
    },
    async fetch(threadId) {
      const res = await fetch(`${base}/${encodeURIComponent(threadId)}`, {
        headers: headers(),
      })
      if (!res.ok) throw new Error(`Session not found: ${res.status}`)
      const session: unknown = await res.json()
      const id = idOf(session)
      if (!id || id !== threadId)
        throw new Error(
          'Invalid ADK session fetch response: expected an object with a non-empty string "id".'
        )
      return {
        status: "regular" as const,
        remoteId: id,
        externalId: id,
        title: titleOf(session),
      }
    },
  }
}

/*
 * Citation markers in an agent's answer: "[S3]", or "[S1, S3]", each naming a
 * passage by the ref its tool result gave it (see sources.tsx).
 */

/** "[S3]", or several at once: "[S1, S3]". */
const MARKER = /\[([A-Z]{1,3}\d{1,4}(?:\s*,\s*[A-Z]{1,3}\d{1,4})*)\]/g
export const REF_HREF = "#source-"

const refsIn = (marker: string) => marker.split(",").map((ref) => ref.trim())

/** The refs a text cites, first citation first. */
export function citedRefs(text: string): string[] {
  const refs = new Set<string>()
  for (const match of text.matchAll(MARKER)) {
    for (const ref of refsIn(match[1] ?? "")) refs.add(ref)
  }
  return [...refs]
}

type MdNode = {
  type: string
  value?: string
  url?: string
  children?: MdNode[]
}

/**
 * A remark plugin: each "[S3]" in the text becomes a link to `#source-S3`,
 * which `SourceAnchor` draws as a citation. Code and links are left alone.
 */
export function remarkSourceRefs() {
  return (tree: MdNode) => linkRefs(tree)
}

function linkRefs(node: MdNode): void {
  if (!node.children || node.type === "link" || node.type === "linkReference")
    return
  const children: MdNode[] = []
  for (const child of node.children) {
    const text = child.type === "text" ? (child.value ?? "") : ""
    let last = 0
    for (const match of text.matchAll(MARKER)) {
      const start = match.index ?? 0
      if (start > last) {
        // The space before a citation doesn't break: it stays with its word.
        const before = text.slice(last, start).replace(/ $/, "\u00a0")
        children.push({ type: "text", value: before })
      }
      for (const ref of refsIn(match[1] ?? "")) {
        children.push({
          type: "link",
          url: `${REF_HREF}${ref}`,
          children: [{ type: "text", value: `[${ref}]` }],
        })
      }
      last = start + match[0].length
    }
    if (last === 0) {
      linkRefs(child)
      children.push(child)
    } else if (last < text.length) {
      children.push({ type: "text", value: text.slice(last) })
    }
  }
  node.children = children
}

import * as React from "react"
import { useAuiState, type ThreadMessage } from "@assistant-ui/react"
import { cn } from "cn"

import { MarkdownText } from "@/components/assistant-ui/elements/markdown-text"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Icon } from "@/components/forge/icon"

import { useAssistantSettings } from "./assistant-context"
import { REF_HREF, citedRefs, remarkSourceRefs } from "./source-refs"

/*
 * Cited sources. An agent's tools return passages that each carry a ref
 * ("S3"); the agent cites them inline as "[S3]". The tool results stream with
 * the answer, in the same message, so the console resolves every ref from
 * them: no second channel, and the sources come back with the conversation.
 */

/** A document an answer can cite; its passages are listed together. */
export type AssistantSourceDocument = {
  /** Identifies the document. */
  key: string
  /** Its name, e.g. the filename. */
  title: string
  /** Where it's from, e.g. the team. */
  subtitle?: string
  /** Opens the document, in a new tab. */
  href?: string
}

/** A passage a tool returned, which the agent cites by `ref`. */
export type AssistantSource = {
  /** What the agent writes in brackets, e.g. "S3". */
  ref: string
  document: AssistantSourceDocument
  /** Where in the document: section, page, sheet. */
  location?: string
  /** The passage, shortened. */
  excerpt?: string
}

/** What a search call looked through and found, for its card. */
export type AssistantSearch = {
  /** What it searched, by name, e.g. the knowledge bases. */
  searched: string[]
  /** The passages it found; none when nothing was relevant enough. */
  found: number
  /** The documents they're from. */
  documents: number
}

/**
 * How answers cite what the agent's tools found. Make it once (at module
 * scope or in `useMemo`): each message's sources are read once per config.
 */
export type AssistantSourcesConfig = {
  /** The sources in a finished tool call's result; [] for other tools. */
  fromToolCall: (toolName: string, result: unknown) => AssistantSource[]
  /**
   * The search a finished tool call made, which its card says in place of
   * "Used tool: <name>" ("Searched Claims knowledge · 5 passages in 3
   * documents"); undefined for calls that aren't searches.
   */
  searchOf?: (toolName: string, result: unknown) => AssistantSearch | undefined
}

/* -------------------------------------------------------------------------- */
/* Where the refs point                                                       */
/* -------------------------------------------------------------------------- */

type Cached = { config: AssistantSourcesConfig; sources: AssistantSource[] }
// A message's sources, read once per version of it.
const perMessage = new WeakMap<ThreadMessage, Cached>()

function sourcesOf(
  message: ThreadMessage,
  config: AssistantSourcesConfig
): AssistantSource[] {
  const cached = perMessage.get(message)
  if (cached?.config === config) return cached.sources
  const sources: AssistantSource[] = []
  if (message.role === "assistant") {
    for (const part of message.content) {
      if (part.type !== "tool-call" || part.result === undefined) continue
      if (part.isError) continue
      try {
        sources.push(...config.fromToolCall(part.toolName, part.result))
      } catch {
        // A result the config can't read cites nothing.
      }
    }
  }
  perMessage.set(message, { config, sources })
  return sources
}

/** Every source the conversation's tools returned, by ref. */
function useThreadSources() {
  const config = useAssistantSettings().sources
  const messages = useAuiState((s) => s.thread.messages)
  return React.useMemo(() => {
    const byRef = new Map<string, AssistantSource>()
    if (config) {
      for (const message of messages) {
        for (const source of sourcesOf(message, config)) {
          byRef.set(source.ref, source)
        }
      }
    }
    return byRef
  }, [messages, config])
}

/** The refs this message cites, in order: [S7, S2] numbers S7 as 1. */
function useMessageCitations() {
  const text = useAuiState((s) =>
    s.message.content
      .map((part) => (part.type === "text" ? part.text : ""))
      .join("\n")
  )
  return React.useMemo(() => citedRefs(text), [text])
}

/* -------------------------------------------------------------------------- */
/* Citations in the text                                                      */
/* -------------------------------------------------------------------------- */

const chip =
  "inline-flex h-4 min-w-4 shrink-0 items-center justify-center rounded-(--radius-chip) bg-muted px-1 font-sans text-3xs leading-none font-medium text-muted-foreground tabular-nums"

/**
 * A citation: its number in this answer, opening the passage behind it on
 * hover or press. A ref no tool returned stays the text the agent wrote.
 */
function SourceRef({ id }: { id: string }) {
  const byRef = useThreadSources()
  const cited = useMessageCitations()
  const source = byRef.get(id)
  const number = cited.indexOf(id) + 1
  if (!source || number === 0) return <>{`[${id}]`}</>
  return (
    <Popover>
      {/* A span, not a button: an inline box keeps the no-break space
          before it, so a citation never wraps away from its word. */}
      <PopoverTrigger
        openOnHover
        delay={150}
        nativeButton={false}
        render={<span />}
        aria-label={`Source ${number}: ${source.document.title}`}
        className="relative -top-px ms-0.5 cursor-pointer rounded-(--radius-chip) bg-muted px-1 py-px font-sans text-3xs font-medium whitespace-nowrap text-muted-foreground tabular-nums transition-colors duration-100 hover:bg-accent hover:text-foreground data-popup-open:bg-accent data-popup-open:text-foreground"
      >
        {number}
      </PopoverTrigger>
      <PopoverContent side="top" align="start" className="w-80 gap-2">
        <SourceCard source={source} number={number} />
      </PopoverContent>
    </Popover>
  )
}

function SourceCard({
  source,
  number,
}: {
  source: AssistantSource
  number: number
}) {
  const { document } = source
  const where = [document.subtitle, source.location].filter(Boolean).join(" · ")
  return (
    <>
      <div className="flex min-w-0 items-start gap-2">
        <span className={cn(chip, "mt-px")}>{number}</span>
        <div className="grid min-w-0 gap-0.5">
          <p className="truncate font-medium text-foreground">
            {document.title}
          </p>
          {where && <p className="text-muted-foreground">{where}</p>}
        </div>
      </div>
      {source.excerpt && (
        <p className="line-clamp-4 text-muted-foreground">{source.excerpt}</p>
      )}
      {document.href && (
        <a
          href={document.href}
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1 self-start font-medium text-foreground underline-offset-2 hover:underline"
        >
          Open document
          <Icon icon="external" size={13} />
        </a>
      )}
    </>
  )
}

/** Markdown links: citations from `remarkSourceRefs`, else a plain link. */
function SourceAnchor({
  href,
  className,
  children,
  ...props
}: React.ComponentProps<"a">) {
  if (href?.startsWith(REF_HREF))
    return <SourceRef id={href.slice(REF_HREF.length)} />
  return (
    <a
      href={href}
      className={cn(
        "aui-md-a text-primary underline underline-offset-2 hover:text-primary/80",
        className
      )}
      {...props}
    >
      {children}
    </a>
  )
}

const sourceComponents = { a: SourceAnchor }
const sourcePlugins = [remarkSourceRefs]

/** An answer's text, its "[S3]" citations drawn as numbered sources. */
export function SourcedMarkdownText() {
  const config = useAssistantSettings().sources
  if (!config) return <MarkdownText />
  return (
    <MarkdownText components={sourceComponents} remarkPlugins={sourcePlugins} />
  )
}

/* -------------------------------------------------------------------------- */
/* Sources under the answer                                                   */
/* -------------------------------------------------------------------------- */

type DocumentGroup = {
  document: AssistantSourceDocument
  sources: AssistantSource[]
}

function groupByDocument(sources: AssistantSource[]): DocumentGroup[] {
  const groups = new Map<string, DocumentGroup>()
  for (const source of sources) {
    const group = groups.get(source.document.key)
    if (group) group.sources.push(source)
    else
      groups.set(source.document.key, {
        document: source.document,
        sources: [source],
      })
  }
  return [...groups.values()]
}

function DocumentTitle({ document }: { document: AssistantSourceDocument }) {
  return document.href ? (
    <a
      href={document.href}
      target="_blank"
      rel="noreferrer"
      className="truncate font-medium text-foreground underline-offset-2 hover:underline"
    >
      {document.title}
    </a>
  ) : (
    <span className="truncate font-medium text-foreground">
      {document.title}
    </span>
  )
}

function DocumentRow({
  group,
  cited,
}: {
  group: DocumentGroup
  cited: boolean
}) {
  const locations = [
    ...new Set(group.sources.map((s) => s.location).filter(Boolean)),
  ]
  return (
    <li className="flex min-w-0 items-start gap-2 text-xs">
      {cited ? (
        <span className="mt-px flex shrink-0 gap-0.5">
          {group.sources.map((source) => (
            <SourceRef key={source.ref} id={source.ref} />
          ))}
        </span>
      ) : (
        <Icon
          icon="file"
          size={14}
          className="mt-px shrink-0 text-muted-foreground"
        />
      )}
      <div className="grid min-w-0 flex-1 gap-px">
        <div className="flex min-w-0 items-baseline gap-2">
          <DocumentTitle document={group.document} />
          {group.document.subtitle && (
            <span className="ms-auto shrink-0 text-2xs text-subtle">
              {group.document.subtitle}
            </span>
          )}
        </div>
        {locations.length > 0 && (
          <span className="truncate text-2xs text-muted-foreground">
            {locations.join(" · ")}
          </span>
        )}
      </div>
    </li>
  )
}

const plural = (count: number, one: string) =>
  `${count} ${one}${count === 1 ? "" : "s"}`

/* -------------------------------------------------------------------------- */
/* Search calls                                                               */
/* -------------------------------------------------------------------------- */

/**
 * A search call's card label: what it searched and what it found, e.g.
 * "Searched **Member knowledge** and **Claims knowledge** · 5 passages in 3
 * documents", or "· nothing relevant" when it found nothing to answer from.
 */
export function SearchLabel({ search }: { search: AssistantSearch }) {
  const [first, second, ...rest] = search.searched
  return (
    <>
      Searched {first ? <b>{first}</b> : "the knowledge base"}
      {second &&
        (rest.length ? (
          <> and {rest.length + 1} more</>
        ) : (
          <>
            {" "}
            and <b>{second}</b>
          </>
        ))}
      <span className="text-subtle">
        {" · "}
        {search.found
          ? `${plural(search.found, "passage")} in ${plural(search.documents, "document")}`
          : "nothing relevant"}
      </span>
    </>
  )
}

/**
 * The documents under an answer: the ones it cites, numbered as in the text,
 * then the others its searches found. Shown once the answer is complete.
 */
export function MessageSources() {
  const config = useAssistantSettings().sources
  const message = useAuiState((s) => s.message)
  const byRef = useThreadSources()
  const cited = useMessageCitations()
  if (!config || message.role !== "assistant") return null
  if (message.status?.type === "running") return null

  const citedSources = cited.flatMap((ref) => byRef.get(ref) ?? [])
  const citedGroups = groupByDocument(citedSources)
  const citedKeys = new Set(citedGroups.map((g) => g.document.key))
  const searched = groupByDocument(sourcesOf(message, config)).filter(
    (g) => !citedKeys.has(g.document.key)
  )
  if (!citedGroups.length && !searched.length) return null

  return (
    <section
      aria-label="Sources"
      data-slot="assistant-message-sources"
      className="mt-3 grid gap-1.5 border-t border-border pt-2.5"
    >
      {citedGroups.length > 0 && (
        <>
          <p className="text-2xs font-medium text-muted-foreground">Sources</p>
          <ul className="grid gap-1.5">
            {citedGroups.map((group) => (
              <DocumentRow key={group.document.key} group={group} cited />
            ))}
          </ul>
        </>
      )}
      {searched.length > 0 && (
        <Collapsible>
          <CollapsibleTrigger className="group/searched inline-flex items-center gap-1 text-2xs font-medium text-muted-foreground hover:text-foreground">
            {citedGroups.length ? "Also searched" : "Searched"}{" "}
            {plural(searched.length, "document")}
            <Icon
              icon="down"
              size={13}
              className="transition-transform duration-150 group-data-panel-open/searched:rotate-180"
            />
          </CollapsibleTrigger>
          <CollapsibleContent>
            <ul className="mt-1.5 grid gap-1.5">
              {searched.map((group) => (
                <DocumentRow
                  key={group.document.key}
                  group={group}
                  cited={false}
                />
              ))}
            </ul>
          </CollapsibleContent>
        </Collapsible>
      )}
    </section>
  )
}

import type {
  AdkEvent,
  AdkStreamCallback,
} from "@assistant-ui/react-google-adk"

/** Forge's server-owned invocation envelope. */
export const TURN_METADATA_KEY = "forge:turn"
/** Browser-only response state. Never send this key back to an agent. */
export const CLIENT_TURN_STATE_KEY = "forge:turn:client"

type TurnStatus = "running" | "succeeded" | "failed" | "cancelled"
export type ClientTurnOutcome = {
  status: TurnStatus
  errorCode?: string
  errorMessage?: string
}
type ServerTurnOutcome = ClientTurnOutcome & { version: 1; runId: string }
type Failure = { errorCode: string; errorMessage: string }

const record = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

export function clientTurnOutcome(
  value: unknown
): ClientTurnOutcome | undefined {
  if (
    !record(value) ||
    typeof value.status !== "string" ||
    !["running", "succeeded", "failed", "cancelled"].includes(
      String(value.status)
    )
  )
    return undefined
  return {
    status: value.status as TurnStatus,
    ...(typeof value.errorCode === "string" && { errorCode: value.errorCode }),
    ...(typeof value.errorMessage === "string" && {
      errorMessage: value.errorMessage,
    }),
  }
}

const serverTurnOutcome = (value: unknown): ServerTurnOutcome | undefined => {
  const outcome = clientTurnOutcome(value)
  return outcome &&
    record(value) &&
    value.version === 1 &&
    typeof value.runId === "string" &&
    /^[a-f0-9]{32}$/i.test(value.runId)
    ? { ...outcome, version: 1, runId: value.runId }
    : undefined
}

const filteredReasons = new Set([
  "SAFETY",
  "RECITATION",
  "BLOCKLIST",
  "PROHIBITED_CONTENT",
  "SPII",
  "LANGUAGE",
  "IMAGE_SAFETY",
  "IMAGE_RECITATION",
  "IMAGE_OTHER",
  "IMAGE_PROHIBITED_CONTENT",
])

const finishFailure = (reason: string | undefined): Failure | undefined => {
  if (reason === "MAX_TOKENS")
    return {
      errorCode: reason,
      errorMessage:
        "The reply reached the model's output limit before it finished. Try asking for a shorter answer or continue the reply.",
    }
  if (reason && filteredReasons.has(reason))
    return {
      errorCode: reason,
      errorMessage:
        "The model's safety filters stopped this reply. Try rephrasing your request.",
    }
  if (reason === "MALFORMED_FUNCTION_CALL" || reason === "UNEXPECTED_TOOL_CALL")
    return {
      errorCode: reason,
      errorMessage:
        "The model couldn't complete a tool call. Please try again.",
    }
  return undefined
}

const interrupted: Failure = {
  errorCode: "STREAM_INTERRUPTED",
  errorMessage:
    "The connection ended before the assistant finished replying. Please try again.",
}
const invalidOutcome: Failure = {
  errorCode: "INVALID_TURN_OUTCOME",
  errorMessage:
    "The assistant returned an incomplete response. Please try again.",
}

/** Read both shapes accepted by ADK, without leaving aliases that override a split error event. */
export function normalizeAdkEvent(event: AdkEvent): AdkEvent {
  const raw = event as AdkEvent & Record<string, unknown>
  const result = { ...raw }
  for (const [camel, snake] of [
    ["errorCode", "error_code"],
    ["errorMessage", "error_message"],
    ["finishReason", "finish_reason"],
    ["customMetadata", "custom_metadata"],
    ["invocationId", "invocation_id"],
  ] as const) {
    if (result[camel] === undefined && raw[snake] !== undefined)
      (result as Record<string, unknown>)[camel] = raw[snake]
    delete result[snake]
  }
  if (result.actions) {
    const actions = result.actions as AdkEvent["actions"] &
      Record<string, unknown>
    const state = actions.stateDelta ?? actions.state_delta
    const clean = { ...actions }
    delete clean.state_delta
    if (record(state)) {
      clean.stateDelta = { ...state }
      delete clean.stateDelta[CLIENT_TURN_STATE_KEY]
    }
    result.actions = clean
  }
  return result
}

/** The same error interpretation for live replies and persisted history. */
export function adkEventFailure(event: AdkEvent): Failure | undefined {
  if (event.errorCode || event.errorMessage)
    return {
      errorCode: event.errorCode || "AGENT_ERROR",
      errorMessage:
        event.errorMessage ||
        "The assistant couldn't finish this reply. Please try again.",
    }
  return finishFailure(event.finishReason)
}

/** The SDK skips content on error/interruption events, so replay that content first. */
export function adkEventsForDisplay(raw: AdkEvent): AdkEvent[] {
  const event = normalizeAdkEvent(raw)
  const failed = Boolean(event.errorCode || event.errorMessage)
  // A failure must not be swallowed by the SDK's earlier interruption branch.
  const terminal =
    failed && event.interrupted ? { ...event, interrupted: false } : event
  if ((failed || event.interrupted) && event.content?.parts?.length)
    return [
      {
        ...event,
        errorCode: undefined,
        errorMessage: undefined,
        interrupted: false,
      },
      { ...terminal, content: undefined },
    ]
  return [terminal]
}

const outcomeEvent = (outcome: ClientTurnOutcome): AdkEvent => ({
  id: crypto.randomUUID(),
  actions: { stateDelta: { [CLIENT_TURN_STATE_KEY]: outcome } },
})

/**
 * Keep invocation completion separate from an individual agent's final message.
 * Generic ADK servers may omit Forge's envelope; Forge connections require it.
 * The local outcome survives the SDK joining partial text and error messages.
 */
export function withTurnLifecycle(
  stream: AdkStreamCallback,
  { requireTurnOutcome = false }: { requireTurnOutcome?: boolean } = {}
): AdkStreamCallback {
  return async function* (messages, config) {
    // Closing a completed response must not look like the user's Stop signal
    // to the SDK: only this transport owns and aborts the child request.
    const request = new AbortController()
    const abortRequest = () => request.abort(config.abortSignal.reason)
    config.abortSignal.addEventListener("abort", abortRequest, { once: true })
    try {
      if (config.abortSignal.aborted) return
      yield outcomeEvent({ status: "running" })
      const stateDelta = { ...config.stateDelta }
      delete stateDelta[CLIENT_TURN_STATE_KEY]
      let runId: string | undefined
      let terminal: ServerTurnOutcome | undefined
      let failure: Failure | undefined
      let emittedError = false
      try {
        const events = await stream(messages, {
          ...config,
          stateDelta,
          abortSignal: request.signal,
        })
        for await (const raw of events) {
          if (config.abortSignal.aborted) return
          const event = normalizeAdkEvent(raw)
          const metadata = event.customMetadata
          if (metadata && Object.hasOwn(metadata, TURN_METADATA_KEY)) {
            const outcome = serverTurnOutcome(metadata[TURN_METADATA_KEY])
            if (
              !outcome ||
              (outcome.status === "running"
                ? runId !== undefined
                : runId !== outcome.runId)
            ) {
              failure = invalidOutcome
              request.abort()
              break
            }
            if (outcome.status === "running") {
              runId = outcome.runId
              // Envelopes have no conversation content or agent-owned state.
              continue
            }
            terminal = outcome
            // The outcome is authoritative. Do not wait for a peer/proxy to close
            // its socket; aborting the child also releases the fetch body reader.
            request.abort()
            break
          }
          if (event.errorCode || event.errorMessage) {
            failure = adkEventFailure(event)
            // The ADK accumulator ignores content on an error event. Preserve
            // final full text first: normal ADK semantics replace partial text.
            yield* adkEventsForDisplay(event)
            emittedError = true
          } else {
            failure = finishFailure(event.finishReason) ?? failure
            yield* adkEventsForDisplay(event)
          }
        }
        if (config.abortSignal.aborted) return
        if ((requireTurnOutcome || runId) && !terminal) failure ??= interrupted
      } catch (error) {
        // Stop/replacement is deliberate. A received terminal outcome already
        // establishes the result even if the transport fails while closing.
        if (config.abortSignal.aborted) return
        if (!terminal)
          failure ??= {
            errorCode: "REQUEST_FAILED",
            errorMessage: `The assistant couldn't complete the request: ${error instanceof Error ? error.message : String(error)}`,
          }
      }
      if (terminal?.status === "failed")
        failure = {
          errorCode: terminal.errorCode || failure?.errorCode || "AGENT_ERROR",
          errorMessage:
            terminal.errorMessage ||
            failure?.errorMessage ||
            "The assistant couldn't finish this reply. Please try again.",
        }
      if (failure) {
        const event = outcomeEvent({ status: "failed", ...failure })
        yield emittedError ? event : { ...event, ...failure }
      } else if (terminal?.status === "cancelled") {
        yield outcomeEvent({
          status: "cancelled",
          errorMessage:
            terminal.errorMessage ||
            "The reply was stopped before it finished. Please try again.",
        })
      } else {
        yield outcomeEvent({ status: "succeeded" })
      }
    } finally {
      config.abortSignal.removeEventListener("abort", abortRequest)
      request.abort()
    }
  }
}

import { useAuiState } from "@assistant-ui/react"
import { useAdkSessionState } from "@assistant-ui/react-google-adk"

import { CLIENT_TURN_STATE_KEY, clientTurnOutcome } from "./turn-lifecycle"

/** A failed invocation remains visible even when the SDK merged it into partial text. */
export function AdkTurnStatus() {
  const state = useAdkSessionState()
  const running = useAuiState((s) => s.thread.isRunning)
  const outcome = clientTurnOutcome(state[CLIENT_TURN_STATE_KEY])
  if (
    running ||
    !outcome ||
    (outcome.status !== "failed" && outcome.status !== "cancelled")
  )
    return null
  return (
    <div
      role="alert"
      data-slot="assistant-turn-error"
      className="mx-2 rounded-(--radius-card) border border-danger-border bg-danger-surface p-3 text-xs text-danger-foreground"
    >
      <p className="font-medium">
        {outcome.status === "cancelled"
          ? "Reply stopped"
          : "Reply couldn't finish"}
      </p>
      <p className="mt-1 leading-relaxed">
        {outcome.errorMessage || "Please try again."}
      </p>
    </div>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
  WebSpeechDictationAdapter,
  type AssistantRuntime,
  type AttachmentAdapter,
  type DictationAdapter,
  type FeedbackAdapter,
  type ThreadMessage,
} from "@assistant-ui/react"
import {
  createAdkSessionAdapter,
  createAdkStream,
  useAdkRuntime,
  type AdkEvent,
  type AdkStreamCallback,
  type UseAdkRuntimeOptions,
} from "@assistant-ui/react-google-adk"
import { noteWholeReply } from "@/components/assistant-ui/elements/whole-replies"

import { defaultAttachments } from "./attachments"
import { followUpsRequest, type FollowUpsOption } from "./follow-ups"
import {
  defaultModelStateDelta,
  defaultThinkingLevels,
  nearestThinkingLevel,
  type AssistantModel,
  type ModelSelection,
  type ModelSettings,
  type ThinkingLevel,
} from "./model-settings"
import { withSessionTitles } from "./session-titles"
import {
  createHistoryFeedback,
  registerHistoryFeedback,
} from "./history-feedback"
import { createAdkHistoryLoader } from "./history-snapshot"
import { CLIENT_TURN_STATE_KEY, withTurnLifecycle } from "./turn-lifecycle"

type Headers = Record<string, string> | (() => Record<string, string>)

/** Fetch, list and delete a session's artifacts (direct ADK connections). */
export type AdkArtifactsApi = ReturnType<
  typeof createAdkSessionAdapter
>["artifacts"]

export type UseAdkAssistantOptions = Omit<
  UseAdkRuntimeOptions,
  "stream" | "sessionAdapter"
> & {
  /**
   * Proxy mode: your own API route, e.g. one built with `createAdkApiRoute`
   * from `@assistant-ui/react-google-adk/server`.
   */
  api?: string
  /**
   * Direct mode: an ADK server (`adk api_server`, `adk web`). Its sessions
   * become the thread list, and artifacts can be fetched.
   */
  adk?: { url: string; appName: string; userId: string }
  /** Sent with every request; a function is read per request. */
  headers?: Headers
  /**
   * ADK session state sent with every run, read as it's sent: e.g. what the
   * person is looking at, `() => ({ page_context: currentPage() })`. The
   * model section's keys win over the same keys here.
   */
  runState?: () => Record<string, unknown> | undefined
  /** Require Forge's explicit invocation outcome; enable for Forge runtime connections. */
  requireTurnOutcome?: boolean
  /** A custom transport instead of `api` / `adk` (tests, mocks). */
  stream?: AdkStreamCallback
  /**
   * Voice input for the composer's mic button; the words appear in the input
   * as they're recognised. Default: the browser's own speech recognition
   * (Web Speech API), where the browser has it. `false` turns it off; any
   * assistant-ui `DictationAdapter` (e.g. a server speech-to-text) replaces it.
   */
  dictation?: boolean | DictationAdapter
  /**
   * What the composer's attach button takes. Default: images and documents
   * (PDF, Word, PowerPoint) as inline parts of the message, which ADK passes
   * to the model, and text files (txt, md, csv, html, json) as text
   * (`./attachments`). `false` turns attaching off; any assistant-ui
   * `AttachmentAdapter` replaces it.
   */
  attachments?: boolean | AttachmentAdapter
  /**
   * Shows thumbs up / down on the agent's replies and receives each rating,
   * e.g. to store it next to the ADK session. Without it the buttons are
   * hidden.
   */
  onFeedback?: (feedback: AssistantFeedback) => void | Promise<void>
  /**
   * Models to choose from in the composer's model section (`showModels`).
   * They may arrive after the first render, e.g. from the agent server.
   */
  models?: AssistantModel[]
  /** Default: the first model. */
  defaultModel?: string
  /**
   * Thinking levels for the model section, from least to most thinking; a
   * model's own `thinkingLevels` narrows them. Default: off, low, medium,
   * high.
   */
  thinkingLevels?: ThinkingLevel[]
  /**
   * Default: "medium" when it's a level, otherwise the first. A model that
   * doesn't offer it gets the nearest level it does.
   */
  defaultThinkingLevel?: string
  /**
   * Turns the model section's selection into the ADK `stateDelta` sent with
   * each run. Default: `{ model, thinking_level }`.
   */
  modelStateDelta?: (selection: ModelSelection) => Record<string, unknown>
  /**
   * Asks the agent server for follow-up questions after each reply: every run
   * sends `forge:suggest_follow_ups` in its state (true, or `{ count }`, 1–5),
   * and once the turn ends with a reply, the server's model writes a few
   * messages the person might send next (forge_common's `FollowUpsPlugin`,
   * in Forge's agent runtimes). The thread shows them above the composer as
   * chips that send them. A server that doesn't know it ignores it, or refuses
   * the key if it checks the state it's sent.
   */
  suggestFollowUps?: FollowUpsOption
}

/**
 * The assistant-ui runtime for a Google ADK agent. Pass the result to
 * `AssistantScreen`: `runtime`, `artifacts` and the model section's
 * `modelSettings`.
 */
export function useAdkAssistant({
  api,
  adk,
  headers,
  runState,
  stream,
  requireTurnOutcome = false,
  dictation = true,
  attachments = true,
  onFeedback,
  models = noModels,
  defaultModel,
  thinkingLevels = defaultThinkingLevels,
  defaultThinkingLevel,
  modelStateDelta = defaultModelStateDelta,
  suggestFollowUps,
  ...options
}: UseAdkAssistantOptions) {
  // Headers may change (a refreshed token) without rebuilding the transport:
  // the getter is created once and reads the latest headers per request.
  const headersRef = useRef(headers)
  useEffect(() => {
    headersRef.current = headers
  })
  const [getHeaders] = useState(() => () => {
    const current = headersRef.current
    return typeof current === "function" ? current() : (current ?? {})
  })

  const { url, appName, userId } = adk ?? {}
  const connection = useMemo(() => {
    const history = createHistoryFeedback()
    if (stream) return { stream, history }
    if (url && appName && userId) {
      const session = createAdkSessionAdapter({
        apiUrl: url,
        appName,
        userId,
        headers: getHeaders,
      })
      return {
        history,
        stream: createAdkStream({
          api: url,
          appName,
          userId,
          headers: getHeaders,
        }),
        // Listed with their titles, which the server keeps (`session-titles`).
        sessionAdapter: withSessionTitles(session.adapter, {
          url,
          appName,
          userId,
          headers: getHeaders,
        }),
        load: createAdkHistoryLoader({
          url,
          appName,
          userId,
          headers: getHeaders,
        }),
        artifacts: session.artifacts,
      }
    }
    if (api)
      return { history, stream: createAdkStream({ api, headers: getHeaders }) }
    throw new Error(
      "useAdkAssistant needs `api` (your route), `adk` (an ADK server) or `stream`."
    )
  }, [stream, url, appName, userId, api, getHeaders])

  const history = connection.history
  const sessionAdapter = useMemo(
    () =>
      connection.sessionAdapter
        ? history.wrapAdapter(connection.sessionAdapter)
        : undefined,
    [connection, history]
  )
  const load = useMemo(() => {
    const loader = options.load ?? connection.load
    return loader ? history.wrapLoad(loader) : undefined
  }, [options.load, connection, history])

  const { settings: modelSettings, shown: modelsShown } = useModelSettings({
    models,
    defaultModel,
    thinkingLevels,
    defaultThinkingLevel,
  })

  // Runs carry `runState`, the request for follow-ups when they're on and,
  // while it's shown, the model section's selection as ADK state.
  const selectionRef = useRef<ModelSelection | undefined>(undefined)
  const toStateDeltaRef = useRef(modelStateDelta)
  const runStateRef = useRef(runState)
  const followUpsRef = useRef(suggestFollowUps)
  useEffect(() => {
    const { model, thinkingLevel } = modelSettings
    selectionRef.current = modelsShown ? { model, thinkingLevel } : undefined
    toStateDeltaRef.current = modelStateDelta
    runStateRef.current = runState
    followUpsRef.current = suggestFollowUps
  })
  const send = useCallback<AdkStreamCallback>(
    async function* (messages, config) {
      const streamWithLifecycle = withTurnLifecycle(
        async function* (messages, config) {
          if (load) {
            const session = await config.initialize()
            history.assertReady(session.externalId ?? session.remoteId)
          }
          const selection = selectionRef.current
          const stateDelta = {
            ...config.stateDelta,
            ...runStateRef.current?.(),
            ...followUpsRequest(followUpsRef.current),
            ...(selection && toStateDeltaRef.current(selection)),
          }
          // This key is response-only, including when a caller copied session state.
          delete stateDelta[CLIENT_TURN_STATE_KEY]
          const events = await connection.stream(messages, {
            ...config,
            stateDelta,
          })
          // A server that streams sends partial events as the model writes;
          // one that doesn't sends each reply whole once it's done, and the
          // thread writes those in word by word, as if they streamed.
          let streamed = false
          for await (const event of events) {
            if (event.partial) streamed = true
            else if (!streamed) noteWholeReplies(event)
            yield event
          }
        },
        { requireTurnOutcome }
      )
      yield* await streamWithLifecycle(messages, config)
    },
    [connection, requireTurnOutcome, history, load]
  )

  // Created once: the browser adapter starts a fresh recognition per session.
  const [browserDictation] = useState(() =>
    WebSpeechDictationAdapter.isSupported()
      ? new WebSpeechDictationAdapter()
      : undefined
  )
  const dictationAdapter =
    dictation === true ? browserDictation : dictation || undefined
  // Created once, like the dictation adapter.
  const [defaultAttachmentAdapter] = useState(defaultAttachments)
  const attachmentAdapter =
    attachments === true ? defaultAttachmentAdapter : attachments || undefined
  // Created once: reads the latest handler and session for each rating.
  const onFeedbackRef = useRef(onFeedback)
  const runtimeRef = useRef<AssistantRuntime | null>(null)
  // Only direct connections know ADK session ids; other threads are local.
  const sessionsRef = useRef(false)
  const [feedbackAdapter] = useState<FeedbackAdapter>(() => ({
    submit: ({ message, type, comment }) => {
      const feedback: AssistantFeedback = {
        type,
        message,
        text: messageText(message),
        sessionId: sessionsRef.current
          ? runtimeRef.current?.threads.mainItem.getState().remoteId
          : undefined,
        ...(comment && { comment }),
      }
      Promise.resolve()
        .then(() => onFeedbackRef.current?.(feedback))
        .catch((error: unknown) => console.error("Feedback failed:", error))
    },
  }))
  const hasFeedback = Boolean(onFeedback)

  const adapters = useMemo(
    () => ({
      dictation: dictationAdapter,
      attachments: attachmentAdapter,
      ...(hasFeedback && { feedback: feedbackAdapter }),
      ...options.adapters,
    }),
    [
      dictationAdapter,
      attachmentAdapter,
      hasFeedback,
      feedbackAdapter,
      options.adapters,
    ]
  )

  const runtime = useAdkRuntime({
    ...options,
    adapters,
    stream: send,
    sessionAdapter,
    load,
  })
  useEffect(() => registerHistoryFeedback(runtime, history), [runtime, history])
  useEffect(() => {
    onFeedbackRef.current = onFeedback
    runtimeRef.current = runtime
    sessionsRef.current = Boolean(connection.sessionAdapter)
  })

  return {
    runtime,
    artifacts: connection.artifacts,
    modelSettings,
  }
}

/** The agent's text in an event that arrived whole, for `MarkdownText`. */
function noteWholeReplies(event: AdkEvent) {
  if (event.author === "user") return
  for (const part of event.content?.parts ?? []) {
    if (part.text && !part.thought) noteWholeReply(part.text)
  }
}

/** A thumbs up or down on one of the agent's replies. */
export type AssistantFeedback = {
  type: "positive" | "negative"
  /** The rated reply. */
  message: ThreadMessage
  /** The reply's text, for logs and review queues. */
  text: string
  /** The reply's ADK session, for direct `adk` connections once it exists. */
  sessionId: string | undefined
  /** A comment, when the UI collects one. */
  comment?: string
}

const messageText = (message: ThreadMessage) =>
  message.content
    .flatMap((part) => (part.type === "text" ? [part.text] : []))
    .join("\n\n")

const noModels: AssistantModel[] = []

function useModelSettings({
  models,
  defaultModel,
  thinkingLevels,
  defaultThinkingLevel,
}: {
  models: AssistantModel[]
  defaultModel: string | undefined
  thinkingLevels: ThinkingLevel[]
  defaultThinkingLevel: string | undefined
}) {
  // What the person chose; what's selected follows the models as they load
  // or change: the choice while it's one of them, else the default, else
  // the first.
  const [chosenModel, setModel] = useState<string>()
  const [chosenLevel, setThinkingLevel] = useState<string>()
  const listed = (id: string | undefined) =>
    id !== undefined && models.some((option) => option.id === id)
  const model = listed(chosenModel)
    ? chosenModel
    : listed(defaultModel)
      ? defaultModel
      : (models[0]?.id ?? defaultModel)

  // As a string, so a new array with the same levels keeps the same list.
  const offered = models
    .find((option) => option.id === model)
    ?.thinkingLevels?.join(" ")
  const modelLevels = useMemo(() => {
    if (offered === undefined) return thinkingLevels
    const ids = offered.split(" ")
    return thinkingLevels.filter((level) => ids.includes(level.id))
  }, [thinkingLevels, offered])
  const preferred =
    chosenLevel ??
    defaultThinkingLevel ??
    (thinkingLevels.some((level) => level.id === "medium")
      ? "medium"
      : (thinkingLevels[0]?.id ?? ""))
  const thinkingLevel =
    nearestThinkingLevel(modelLevels, thinkingLevels, preferred) ?? preferred

  const [shownBy, setShownBy] = useState(0)
  const show = useCallback(() => {
    setShownBy((count) => count + 1)
    return () => setShownBy((count) => count - 1)
  }, [])

  const settings = useMemo<ModelSettings>(
    () => ({
      models,
      thinkingLevels: modelLevels,
      model,
      thinkingLevel,
      setModel,
      setThinkingLevel,
      show,
    }),
    [models, modelLevels, model, thinkingLevel, show]
  )
  return { settings, shown: shownBy > 0 }
}
